singularity.ascended-marginals-are-diago:
"""singularity.ascended-marginals-are-diagonal: exact checks.

Boundary modes are realised by Jordan-Wigner on N = 2, 3, 4 modes: v_k = Z x ... x Z x E_12 x 1 x
... x 1, number basis |b>, total parity Gamma = diag((-1)^popcount(b)). (P) is evenness,
Gamma rho Gamma = rho (premise p-univalence).
(1) General case, by linearity: every even matrix unit E_bc (popcount(b) = popcount(c) mod 2) has
tr(E_bc v_k) = tr(E_bc v_k*) = 0 and a diagonal single-mode marginal at every k, for all N <= 4 and
all k. So omega(v_k) = omega(v_k*) = 0 and rho_k is diagonal for every even state, hence equals
E_k(rho_k) (partial trace and pinching coincide), and by the premise's descended form it is the
Gibbs matrix diag(1, x)/(1 + x) with x = (1 - p)/p, checked on sample even states (mixed, complex
coherences). The odd matrix units are exactly those that can carry omega(v_k) (control).
(2) Zero-weight mode: the Gibbs form id/2 requires p = 1/2; a sample even state has p != 1/2 at a
mode (p = 2771/12675), so it is diagonal there but not Gibbs for omega_k = 0.
(3) Parity protection as the special case: the finite-mode model's states (thermofield pairs
c_k|00> + s_k|11> with controlled-Z signs) are supported on configurations of even total
occupation, are even, and have diagonal marginals diag(c_k^2, s_k^2). A parity-mixed state has
marginal coherence 12/25 (control).
"""
from fractions import Fraction as F

import GA
from GA import QI
from tp_premise import premise

MODEL = [(F(3, 5), F(4, 5)), (F(4, 5), F(3, 5)), (F(5, 13), F(12, 13))]


def bit(b, k, n):
    return (b >> (n - 1 - k)) & 1


def popcount(b):
    return bin(b).count("1")


def zeros(D):
    return [[QI(0)] * D for _ in range(D)]


def ket(n, amps):
    rho = zeros(2 ** n)
    for i, a in amps.items():
        for j, b in amps.items():
            rho[i][j] = rho[i][j] + QI(a) * QI(b).conj()
    return rho


def lower(n, k):
    """Jordan-Wigner v_k as a sparse map {column: (row, sign)}: v_k|b> = (-1)^{#occupied before k}|b - e_k>."""
    out = {}
    for b in range(2 ** n):
        if bit(b, k, n):
            sign = (-1) ** sum(bit(b, t, n) for t in range(k))
            out[b] = (b ^ (1 << (n - 1 - k)), sign)
    return out


def expect_lower(rho, n, k):
    """tr(rho v_k) = sum_b rho[b][row(b)] * sign."""
    return sum((rho[b][r] * s for b, (r, s) in lower(n, k).items()), QI(0))


def expect_raise(rho, n, k):
    return sum((rho[r][b] * s for b, (r, s) in lower(n, k).items()), QI(0))


def marginal(rho, k, n):
    out = [[QI(0), QI(0)], [QI(0), QI(0)]]
    for b in range(2 ** n):
        for c in range(2 ** n):
            if all(bit(b, t, n) == bit(c, t, n) for t in range(n) if t != k):
                out[bit(b, k, n)][bit(c, k, n)] = out[bit(b, k, n)][bit(c, k, n)] + rho[b][c]
    return out


def is_even(rho):
    D = len(rho)
    return all(rho[b][c] == 0 for b in range(D) for c in range(D) if (popcount(b) + popcount(c)) % 2)


def even_sample(n):
    """A mixed even state with complex coherences: two even pure states mixed 1/3 : 2/3."""
    ev = [b for b in range(2 ** n) if popcount(b) % 2 == 0]
    if n == 2:
        a = ket(n, {ev[0]: F(3, 5), ev[1]: QI(0, F(4, 5))})
        b = ket(n, {ev[0]: F(5, 13), ev[1]: F(-12, 13)})
    else:
        a = ket(n, {ev[0]: F(1, 2), ev[1]: QI(0, F(1, 2)), ev[2]: F(1, 2), ev[-1]: F(-1, 2)})
        b = ket(n, {ev[0]: F(3, 5), ev[-1]: F(4, 5)})
    return [[a[i][j] * F(1, 3) + b[i][j] * F(2, 3) for j in range(2 ** n)] for i in range(2 ** n)]


def model_state(pairs):
    """Thermofield pairs (R_k, L_k) at qubits (2k, 2k+1), with a controlled-Z sign on the L's."""
    n = 2 * len(pairs)
    amps = {0: F(1)}
    for k, (c, s) in enumerate(pairs):
        new = {}
        for m, a in amps.items():
            new[m] = new.get(m, F(0)) + a * c
            m2 = m | (1 << (n - 1 - 2 * k)) | (1 << (n - 2 - 2 * k))
            new[m2] = new.get(m2, F(0)) + a * s
        amps = new
    cz = {m: (-a if bit(m, 1, n) and bit(m, 3, n) else a) for m, a in amps.items()}
    return n, cz


def check_even_units_have_zero_ladder_expectation_and_diagonal_marginals():
    premise("singularity.p-univalence")
    total = odd_carrying = 0
    for n in (2, 3, 4):
        D = 2 ** n
        for b in range(D):
            for c in range(D):
                Eu = zeros(D)
                Eu[b][c] = QI(1)
                for k in range(n):
                    vk, vks = expect_lower(Eu, n, k), expect_raise(Eu, n, k)
                    mk = marginal(Eu, k, n)
                    if (popcount(b) + popcount(c)) % 2 == 0:
                        assert vk == 0 and vks == 0 and mk[0][1] == 0 and mk[1][0] == 0
                        total += 1
                    elif vk != 0 or vks != 0:
                        odd_carrying += 1
    # even units x modes: n * D^2 / 2 per n; ladder-carrying odd units: 2 * n * D / 2 per n
    assert total == 2 * 8 + 3 * 32 + 4 * 128, total
    assert odd_carrying == 2 * 4 + 3 * 8 + 4 * 16, odd_carrying


def check_even_state_marginals_are_descended_gibbs():
    premise("singularity.p-univalence")
    premise("singularity.descended-form-state-independent")
    seen = 0
    for n in (2, 3, 4):
        rho = even_sample(n)
        assert is_even(rho) and sum((rho[i][i] for i in range(2 ** n)), QI(0)) == 1
        assert any(rho[i][j] != 0 for i in range(2 ** n) for j in range(2 ** n) if i != j)
        for k in range(n):
            assert expect_lower(rho, n, k) == 0 and expect_raise(rho, n, k) == 0
            mk = marginal(rho, k, n)
            assert mk[0][1] == 0 and mk[1][0] == 0
            p = mk[0][0].re
            x = (1 - p) / p
            assert mk[0][0] == 1 / (1 + x) and mk[1][1] == x / (1 + x)
            seen += 1
    assert seen == 9
    # zero-weight mode: the Gibbs form id/2 needs p = 1/2; mode 0 of the 2-mode sample has
    # p = (1/3)(9/25) + (2/3)(25/169), by hand from the two pure components
    m0 = marginal(even_sample(2), 0, 2)
    assert m0[0][0] == F(1, 3) * F(9, 25) + F(2, 3) * F(25, 169) and m0[0][0] != F(1, 2)


def check_parity_protection_is_special_case():
    premise("singularity.p-univalence")
    for pairs in (MODEL[:2], MODEL):
        n, amps = model_state(pairs)
        assert all(popcount(m) % 2 == 0 for m in amps)
        rho = ket(n, amps)
        assert is_even(rho)
        for k in range(n):
            mk = marginal(rho, k, n)
            c, s = pairs[k // 2]
            assert mk == [[QI(c * c), QI(0)], [QI(0), QI(s * s)]]
            assert expect_lower(rho, n, k) == 0
    # control: (3/5)|000> + (4/5)|001> is parity mixed and its third marginal carries coherence 12/25
    rho = ket(3, {0b000: F(3, 5), 0b001: F(4, 5)})
    assert not is_even(rho) and marginal(rho, 2, 3)[0][1] == F(12, 25)
    assert expect_lower(rho, 3, 2) == F(12, 25)

singularity.bosonisation-bridge-s-wave-s:
"""singularity.bosonisation-bridge-s-wave-sector: exact checks.

Finite window W = {-5, ..., 4} of fermion sites, states = sets of occupied sites (sign by sorted order), sea =
the negative sites occupied. a_m = sum_{k, k+m in W} psi_k^dagger psi_{k+m} (m != 0; no normal-ordering
constant is needed for m != 0). B_m, T_m = number operators of the bottom and top m sites.
(1) Current algebra: on all 252 charge-zero states and for m = 1, 2, 3, [a_m, a_{-m}] = B_m - T_m (the edge
    operator identity; B_m - T_m - m vanishes on bulk states, so there [a_m, a_{-m}] = m); for m + n != 0
    (m, n in {+-1, +-2, 3}) [a_m, a_n] = 0 on the 6 bulk states (bottom three sites full, top three empty);
    a_m annihilates the sea for m > 0, and a_{-m} is the transpose of a_m on the charge-zero basis.
(2) KMS restriction: with H = sum_k omega_k N_k, [H, a_m] = -kappa m a_m on every charge-zero state for the
    linear weights omega_k = kappa k (kappa = 1, 3/2), so each current is a weight vector; for omega_k = k^2
    the commutator is not a multiple of a_m. For the window Gibbs state (product, n_k = x^k/(1 + x^k),
    x = e^{-beta kappa}) the KMS identity of the restricted flow gives
    <a_{-m} a_m> = x^m/(1 - x^m) <B_m - T_m>, checked exactly with <a_{-m} a_m> = sum n_{k+m}(1 - n_k)
    (x = 1/2, 2/3; m = 1, 2, 3).
(3) Planck factor: detailed balance h_k = x^{-m} g_k and g_k - h_k = n_{k+m} - n_k as rational-function
    identities in x; the exact finite identity S_K (1 - x^{-m}) = T_K for S_K = sum_{|k| <= K} g_k with
    the boundary sum T_K; and |S_K - m x^m/(1 - x^m)| <= 2m x^(K-m+1)/(x^{-m} - 1) at K = 30, so the infinite
    sum is m/(e^{beta kappa m} - 1). Without (Q): a correlated even state with the same marginals shifts
    <n_{k+m}(1 - n_k)> by its connected correlator (-1/100), so no exact spectrum follows.
The charge-zero Fock isomorphism (cited) is not checked.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

W = list(range(-5, 5))
SEA = frozenset(k for k in W if k < 0)
CHARGE0 = [frozenset(c) for c in combinations(W, 5)]
BULK = [s for s in CHARGE0 if {-5, -4, -3} <= s and not ({2, 3, 4} & s)]


def apply(ops, sv):
    for kind, k in reversed(ops):
        out = {}
        for occ, amp in sv.items():
            if (kind == 'c') == (k in occ):
                continue
            sign = (-1) ** sum(1 for j in occ if j < k)
            new = occ | {k} if kind == 'c' else occ - {k}
            out[new] = out.get(new, F(0)) + sign * amp
        sv = {o: a for o, a in out.items() if a != 0}
    return sv


def add(*terms):
    out = {}
    for sg, d in terms:
        for k, v in d.items():
            out[k] = out.get(k, F(0)) + sg * v
    return {k: v for k, v in out.items() if v != 0}


def cur(m, sv):
    return add(*[(1, apply([('c', k), ('a', k + m)], sv)) for k in W if k + m in W])


def num(sites, sv):
    return {o: a * sum(1 for j in sites if j in o) for o, a in sv.items() if any(j in o for j in sites)}


def comm(m, n, sv):
    return add((1, cur(m, cur(n, sv))), (-1, cur(n, cur(m, sv))))


def check_current_algebra_with_edge_operator():
    premise("singularity.modular-structure-completed-pair")
    ok = len(CHARGE0) == 252 and len(BULK) == 6
    for m in (1, 2, 3):
        bottom, top = W[:m], W[-m:]
        for s in CHARGE0:
            sv = {s: F(1)}
            ok = ok and comm(m, -m, sv) == add((1, num(bottom, sv)), (-1, num(top, sv)))
        for s in BULK:
            ok = ok and comm(m, -m, {s: F(1)}) == {s: F(m)}
        ok = ok and cur(m, {SEA: F(1)}) == {}
        # a_{-m} = a_m^T on the charge-zero basis
        for s in CHARGE0[:60]:
            for t, c in cur(m, {s: F(1)}).items():
                ok = ok and cur(-m, {t: F(1)}).get(s, F(0)) == c
    for (m, n) in [(1, 1), (1, -2), (2, -1), (-1, -2), (3, -1), (2, 1)]:
        for s in BULK:
            ok = ok and comm(m, n, {s: F(1)}) == {}
    _tp_rv = (ok); assert _tp_rv is not False, "check_current_algebra_with_edge_operator"; return _tp_rv


def ket(s):
    return {s: F(1)}


# Weight-vector samples: two kappa, three m, every seventh charge-zero state.
KAPPAS = (F(1), F(3, 2))
M_WEIGHT = (1, 2, -1)
STATE_SAMPLE = CHARGE0[::7]
# Current used in the omega_k = k^2 control.
CONTROL_M = 1
# KMS samples: x = e^{-beta kappa} and m.
X_KMS = (F(1, 2), F(2, 3))
M_KMS = (1, 2, 3)


def check_currents_are_weight_vectors_and_kms_restricts():
    premise("singularity.modular-structure-completed-pair")
    premise("singularity.q-joint-quasi-freeness-s-wave")
    ok = True
    for kappa in KAPPAS:
        for m in M_WEIGHT:
            for s in STATE_SAMPLE:
                sv = ket(s)
                am = cur(m, sv)
                H_am = {o: a * sum(kappa * j for j in o) for o, a in am.items()}
                am_H = {o: a * sum(kappa * j for j in s) for o, a in am.items()}
                ok = ok and add((1, H_am), (-1, am_H)) == {o: -kappa * m * a for o, a in am.items()}
    # control, omega_k = k^2: the hop k + m -> k picks up k^2 - (k + m)^2 = -m (2k + m), which depends on k,
    # so [H, a_m] is not a multiple of a_m
    m = CONTROL_M
    ratios = set()
    for s in STATE_SAMPLE:
        am = cur(m, ket(s))
        H_am = {o: a * sum(j * j for j in o) for o, a in am.items()}
        am_H = {o: a * sum(j * j for j in s) for o, a in am.items()}
        lhs = add((1, H_am), (-1, am_H))
        created = {o: min(o - s) for o in am}
        ok = ok and lhs == {o: -m * (2 * created[o] + m) * a for o, a in am.items()}
        ratios |= {lhs[o] / a for o, a in am.items()}
    ok = ok and max(ratios) > min(ratios)
    for x in X_KMS:
        n = {k: x ** k / (1 + x ** k) for k in W}
        ok = ok and n[0] == F(1, 2)                  # zero chemical potential: half filling at k = 0
        for m in M_KMS:
            lhs = sum(n[k + m] * (1 - n[k]) for k in W if k + m in W)
            edge = sum(n[k] for k in W[:m]) - sum(n[k] for k in W[-m:])
            ok = ok and lhs == x ** m / (1 - x ** m) * edge
    _tp_rv = (ok); assert _tp_rv is not False, "check_currents_are_weight_vectors_and_kms_restricts"; return _tp_rv


def check_planck_factor_and_role_of_q():
    premise("singularity.q-joint-quasi-freeness-s-wave")
    ok = True
    xv = GA.RF.var()
    one = GA.RF.const(1)

    def nk(k):
        if k >= 0:
            p = GA.RF([F(0)] * k + [F(1)])
            return p / (one + p)
        p = GA.RF([F(0)] * (-k) + [F(1)])
        return one / (one + p)
    for m in (1, 2):
        xm = GA.RF([F(0)] * m + [F(1)])
        for k in (-4, -1, 0, 3):
            gk = nk(k + m) * (one - nk(k))
            hk = nk(k) * (one - nk(k + m))
            ok = ok and hk.eqrf(gk / xm) and (gk - hk).eqrf(nk(k + m) - nk(k))
    for x in (F(1, 2), F(2, 3)):
        def n(k):
            return x ** k / (1 + x ** k)
        for m in (1, 2, 3):
            K = 30
            S = sum(n(k + m) * (1 - n(k)) for k in range(-K, K + 1))
            T = sum(n(j) for j in range(K + 1, K + m + 1)) - sum(n(j) for j in range(-K, -K + m))
            ok = ok and S * (1 - x ** (-m)) == T
            planck = m * x ** m / (1 - x ** m)
            bound = 2 * m * x ** (K - m + 1) / (x ** (-m) - 1)
            ok = ok and abs(S - planck) <= bound and S != planck
    # without (Q): correlated even state with the same marginals
    n1 = n2 = F(9, 25)
    eps = F(1, 100)
    pp = [(1 - n1) * (1 - n2), (1 - n1) * n2, n1 * (1 - n2), n1 * n2]        # basis (n_k, n_{k+m})
    qq = [pp[0] + eps, pp[1] - eps, pp[2] - eps, pp[3] + eps]
    ok = ok and qq[2] + qq[3] == n1 and qq[1] + qq[3] == n2 and all(v > 0 for v in qq)
    summand_p = pp[1]                     # n_{k+m} = 1 and n_k = 0
    summand_q = qq[1]
    ok = ok and summand_p == n2 * (1 - n1) and summand_q - summand_p == -eps
    _tp_rv = (ok); assert _tp_rv is not False, "check_planck_factor_and_role_of_q"; return _tp_rv

singularity.bundle-maps-quantise-without:
"""singularity.bundle-maps-quantise-without-hopping: exact matrix identities on a finite truncation.

Model: three points x1, x2, x3 of E, one mode per point (the mode line bundle), Fock space by
Jordan-Wigner (8 x 8 rational matrices), psi_j the annihilators, N_j = psi_j^dag psi_j, joint number
basis |n1 n2 n3>. dGamma(a) = sum_ij a_ij psi_i^dag psi_j.
(1) For a bundle map a = diag(a_1, a_2, a_3) (all eight 0/1 diagonals and two generic ones),
    dGamma(a) = sum_j a_j N_j, it is diagonal in the joint number basis with entry sum_j a_j n_j on
    |n1 n2 n3> (computed independently from the occupations), and commutes with every N_j.
(2) The controlled-Z generator sigma_x sigma_y (sigma = psi^dag psi - psi psi^dag = 2N - 1) is
    diagonal and conserves every occupation: cross-point diagonal products are not hopping.
(3) A cross component: for each ordered pair x != y, dGamma(E_xy) = psi_x^dag psi_y carries
    |(N_x, N_y) = (0, 1)> to |(1, 0)> (the only nonzero entry of that column, value 1) and fails to
    commute with N_x.
EXPORTS the model (PSI, PSID, NOCC, dgamma, basis_state, helpers) for the class-relative no-go.
"""
from fractions import Fraction as F
from itertools import product

import GA
import fock

NPTS = 3
DIM = 2 ** NPTS
GENERIC = ((F(2), F(-7, 2), F(3)), (F(1, 3), F(5), F(-1)))


mm = GA.mat_mul


def madd(A, B, c=1):
    return [[A[i][j] + c * B[i][j] for j in range(len(A[0]))] for i in range(len(A))]


def eye(n):
    return [[F(1) if i == j else F(0) for j in range(n)] for i in range(n)]


def zero(n):
    return [[F(0)] * n for _ in range(n)]


def is_zero(A):
    return all(x == 0 for row in A for x in row)


def comm(A, B):
    return madd(mm(A, B), mm(B, A), -1)


def psi(j):
    """psi_j on (C^2)^(x NPTS): Jordan-Wigner annihilator, point 0 the most significant factor."""
    return fock.to_dense(fock.ann(j, NPTS, fock.MSB), DIM)


PSI = [psi(j) for j in range(NPTS)]
PSID = [[list(r) for r in zip(*p)] for p in PSI]
NOCC = [mm(PSID[j], PSI[j]) for j in range(NPTS)]
SIGMA = [madd(mm(PSID[j], PSI[j]), mm(PSI[j], PSID[j]), -1) for j in range(NPTS)]


def dgamma(a):
    out = zero(DIM)
    for i in range(NPTS):
        for j in range(NPTS):
            if a[i][j] != 0:
                out = madd(out, mm(PSID[i], PSI[j]), a[i][j])
    return out


def basis_state(occ):
    return fock.idx(occ, fock.MSB)


def diag3(vals):
    return [[F(vals[i]) if i == j else F(0) for j in range(NPTS)] for i in range(NPTS)]


DIAGS = [diag3(d) for d in product((0, 1), repeat=NPTS)] + [diag3(g) for g in GENERIC]


def check_bundle_map_quantises_to_multiplication_operator():
    ok = True
    ok = ok and len(DIAGS) == 10
    for a in DIAGS:
        G = dgamma(a)
        want = zero(DIM)
        for j in range(NPTS):
            want = madd(want, NOCC[j], a[j][j])
        ok = ok and G == want
        for occ in product((0, 1), repeat=NPTS):
            s = basis_state(occ)
            val = sum((a[j][j] * occ[j] for j in range(NPTS)), F(0))
            ok = ok and G[s][s] == val and all(G[t][s] == 0 for t in range(DIM) if t != s)
        ok = ok and all(is_zero(comm(G, N)) for N in NOCC)
    ok = ok and all(NOCC[j][basis_state(o)][basis_state(o)] == o[j]
                    for o in product((0, 1), repeat=NPTS) for j in range(NPTS))
    GA.check("dGamma(diag a) = sum a_j N_j, diagonal with entries sum a_j n_j, commuting with every N_j", ok)
    return ok


def check_controlled_z_conserves_occupations():
    ok = True
    for j in range(NPTS):
        ok = ok and SIGMA[j] == madd(madd(zero(DIM), NOCC[j], 2), eye(DIM), -1)
    for x in range(NPTS):
        for y in range(x + 1, NPTS):
            P = mm(SIGMA[x], SIGMA[y])
            ok = ok and all(is_zero(comm(P, N)) for N in NOCC)
            for occ in product((0, 1), repeat=NPTS):
                s = basis_state(occ)
                ok = ok and P[s][s] == (2 * occ[x] - 1) * (2 * occ[y] - 1)
    GA.check("sigma_x sigma_y is diagonal (entries (2n_x - 1)(2n_y - 1)) and conserves every occupation", ok)
    return ok


def check_cross_component_hops():
    ok = True
    for x in range(NPTS):
        for y in range(NPTS):
            if x == y:
                continue
            E = [[F(1) if (r, c) == (x, y) else F(0) for c in range(NPTS)] for r in range(NPTS)]
            G = dgamma(E)
            occ = [0] * NPTS
            occ[y] = 1
            occ2 = [0] * NPTS
            occ2[x] = 1
            col = [G[i][basis_state(occ)] for i in range(DIM)]
            ok = ok and col[basis_state(occ2)] == 1 and sum(1 for c in col if c != 0) == 1
            ok = ok and not is_zero(comm(G, NOCC[x])) and not is_zero(comm(G, NOCC[y]))
    GA.check("psi_x^dag psi_y carries (N_x, N_y) = (0,1) onto (1,0) and does not commute with N_x", ok)
    return ok


EXPORTS = {"NPTS": NPTS, "DIM": DIM, "PSI": PSI, "PSID": PSID, "NOCC": NOCC, "SIGMA": SIGMA,
           "dgamma": dgamma, "basis_state": basis_state, "mm": mm, "madd": madd, "comm": comm,
           "is_zero": is_zero, "eye": eye, "zero": zero}

singularity.causal-epoch-computed-exactl:
"""singularity.causal-epoch-computed-exactly: exact checks of the causal-epoch integral.

All identities are exact: rational functions in u (GA.RF), logarithms as exact formal combinations of
ln p (LogVecs) bounded by rigorous rational intervals, Riemann sums in rational arithmetic.
(1) With r = 2M u^2: the rain worldline (unit energy) has |dt/dr| = 1/(|f| sqrt(1 - f)) = sqrt(r/2M) r/(2M - r)
    (sqrt(1 - f) = sqrt(2M/r) = 1/u inside the horizon), and the integrand in u is 4M u^4/(1 - u^2);
    u^4/(1 - u^2) = -u^2 - 1 + 1/(1 - u^2); (-u^3/3 - u)' = -u^2 - 1 and ((1/2) ln((1+u)/(1-u)))' =
    1/(1 - u^2); with eps = 1 - u^2, (1+u)/(1-u) = (1+u)^2/eps, so the closed form is
    2M ln(1/eps) + 4M (ln(1+u) - u - u^3/3).
(2) The closed form 4M[(1/2) ln((1+u0)/(1-u0)) - u0 - u0^3/3] lies inside the exact lower and upper
    Riemann sums (240 subintervals) of the increasing integrand at u0 = 3/5, 4/5, 9/10; the former closed
    form 2M(ln(1/eps) - 1 + eps) lies outside the bracket at u0 = 9/10.
(3) The expansion: 2M eps <= Delta t - 2M(ln(1/eps) - 8/3 + 2 ln 2) <= 4M eps at u = 9/10, 99/100,
    999/1000, so the remainder is O(eps) with positive sign; the coefficient of ln(1/eps) is the residue
    2M of 1/|f| = r/(2M - r) at r = 2M, and for any energy E > 0 the extra factor E/sqrt(E^2 + |f|) is 1 at
    the horizon, so the coefficient does not depend on E.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise  # noqa: F401 (the claim has no premises)

# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}
_DEN = 1 << 160


def _atanh_bounds(z, K=30):
    """Rational bounds on atanh z for 0 <= z <= 1/3."""
    zz = z * z
    term, part = z, F(0)
    for k in range(K):
        part += term / (2 * k + 1)
        term *= zz
    tail = term / ((2 * K + 1) * (1 - zz))
    return part, part + tail


def _out(lo, hi):
    return F((lo.numerator * _DEN) // lo.denominator, _DEN), \
        F(-((-hi.numerator * _DEN) // hi.denominator), _DEN)


def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer."""
    if n in _LNB:
        return _LNB[n]
    if n == 1:
        return F(0), F(0)
    l2lo, l2hi = _atanh_bounds(F(1, 3))
    l2lo, l2hi = 2 * l2lo, 2 * l2hi
    a = n.bit_length() - 1
    x = F(n, 1 << a)
    zlo, zhi = _atanh_bounds((x - 1) / (x + 1))
    res = _out(a * l2lo + 2 * zlo, a * l2hi + 2 * zhi)
    _LNB[n] = res
    return res


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

MASS = F(3, 2)
U_BRACKET = [F(3, 5), F(4, 5), F(9, 10)]
U_EXPAND = [F(9, 10), F(99, 100), F(999, 1000)]
ENERGIES = [F(1), F(2), F(3, 7)]


def check_integrand_partial_fractions_antiderivative():
    u = GA.RF.var()
    one = GA.RF1
    M4 = GA.RF.const(4 * MASS)
    r = GA.RF.const(2 * MASS) * u * u
    f = one - GA.RF.const(2 * MASS) / r
    absf = GA.RF.const(0) - f
    sqrt_one_minus_f = one / u                       # (1/u)^2 = 2M/r = 1 - f
    assert (sqrt_one_minus_f * sqrt_one_minus_f).eqrf(one - f)
    drdu = r.deriv()
    integrand = (one / (absf * sqrt_one_minus_f)) * drdu
    assert integrand.eqrf(M4 * u * u * u * u / (one - u * u))
    stated = u * (r / (GA.RF.const(2 * MASS) - r)) * drdu       # sqrt(r/2M) = u
    assert stated.eqrf(integrand)
    pf = GA.RF.const(0) - u * u - one + one / (one - u * u)
    assert (u * u * u * u / (one - u * u)).eqrf(pf)
    poly = GA.RF.const(0) - u * u * u / GA.RF.const(3) - u
    assert poly.deriv().eqrf(GA.RF.const(0) - u * u - one)
    logd = GA.RF.const(F(1, 2)) * (one / (one + u) + one / (one - u))
    assert logd.eqrf(one / (one - u * u))
    eps = one - u * u
    assert ((one + u) / (one - u)).eqrf((one + u) * (one + u) / eps)


def closed_form(u0):
    """(log part, rational part) of 4M[(1/2) ln((1+u0)/(1-u0)) - u0 - u0^3/3]."""
    return LogVec.ln_rat((1 + u0) / (1 - u0)) * (2 * MASS), 4 * MASS * (-u0 - u0 ** 3 / 3)


def bracket(u0, n=240):
    """Exact lower and upper Riemann sums of the increasing integrand 4M x^4/(1 - x^2) on [0, u0]."""
    h = u0 / n
    vals = [4 * MASS * (h * i) ** 4 / (1 - (h * i) ** 2) for i in range(n + 1)]
    return sum(vals[:-1]) * h, sum(vals[1:]) * h


def check_closed_form_inside_riemann_bracket():
    for u0 in U_BRACKET:
        lower, upper = bracket(u0)
        L = LogVec.ln_rat((1 + u0) / (1 - u0)) * (2 * MASS)
        rat = 4 * MASS * (-u0 - u0 ** 3 / 3)
        lo, hi = logvec_bounds(L)
        assert lower < lo + rat and hi + rat < upper
    u0 = U_BRACKET[-1]
    eps = 1 - u0 * u0
    lower, upper = bracket(u0)
    olo, ohi = logvec_bounds(LogVec.ln_rat(1 / eps) * (2 * MASS))
    old_rat = 2 * MASS * (eps - 1)
    assert olo + old_rat > upper or ohi + old_rat < lower


def check_expansion_remainder_and_energy_independence():
    for u0 in U_EXPAND:
        eps = 1 - u0 * u0
        L, rat = closed_form(u0)
        expansion = LogVec.ln_rat(1 / eps) * (2 * MASS) + LogVec.ln_int(2) * (4 * MASS)
        lo, hi = logvec_bounds(L - expansion)
        offset = rat + 2 * MASS * F(8, 3)              # closed form minus expansion, rational part
        lo, hi = lo + offset, hi + offset
        assert 2 * MASS * eps <= lo and hi <= 4 * MASS * eps
    r = GA.RF.var()
    twoM = GA.RF.const(2 * MASS)
    absf = twoM / r - GA.RF1
    residue = ((twoM - r) / absf)
    assert residue.eqrf(r) and residue.eval(2 * MASS) == 2 * MASS
    for E in ENERGIES:
        factor_sq = E * E / (E * E + absf.eval(2 * MASS))
        assert absf.eval(2 * MASS) == 0 and factor_sq == 1

singularity.deficit-carried-quanta-corre:
"""singularity.deficit-carried-quanta-correlations: exact checks that the deficit is inter-quanta.

E_N is the joint-number pinching (complete dephasing in the computational basis); C(rho) is the
total correlation sum_k S(rho_k) - S(rho). Entropies are exact formal logarithms (LogVecs) of
rational spectra; positivity is decided by rigorous rational bounds on ln p.
(1) Marginals pass through E_N unchanged when they are diagonal: for every single mode of the
    model's final radiation (eight qubits, controlled-Z scrambled), of the scrambled two-pair state,
    and of two mixed states built to have diagonal marginals (a two-qubit and a three-qubit state
    rho = W diag(p) W^T, W a product of rotations inside the even and inside the odd sector, so
    every coherence joins basis states differing in at least two bits). Control: for a state with a coherent single-mode marginal the marginal of E_N rho differs.
(2) D(rho || E_N rho) = C(rho) - C(E_N rho) exactly on the two mixed states, with D computed from
    its definition tr rho ln rho - tr rho ln E_N rho (ln rho = W diag(ln p) W^T), and D > 0.
(3) For globally pure states (the model's final radiation and the scrambled two-pair state),
    S(rho) = 0 (tr rho^2 = 1) and the deficit S(E_N rho) - S(rho) of the deficit theorem equals the
    total correlation drop, which is the whole descended entropy: for the model run
    3 H(16/25) + H(144/169) nats, the full thermal sum.
"""
from fractions import Fraction as F

import GA
import series
from tp_premise import premise

# --- exact multi-qubit simulator (states: dict {bitmask: amplitude}; qubit R_k = 2k, L_k = 2k+1) ---

def pair_state(c, s, k, state):
    """Tensor the thermofield pair c|00> + s|11> on (R_k, L_k) onto the state."""
    out = {}
    for m, a in state.items():
        out[m] = out.get(m, 0) + a * c
        m2 = m | (1 << (2 * k)) | (1 << (2 * k + 1))
        out[m2] = out.get(m2, 0) + a * s
    return {m: a for m, a in out.items() if a != 0}


def apply_cz(i, j, state):
    return {m: (-a if (m >> i) & 1 and (m >> j) & 1 else a) for m, a in state.items()}


def marginal(qubits, state, nq):
    """Reduced density matrix (unnormalised if the state is) over the listed qubits; bit t of the
    row index is the occupation of qubits[t]."""
    d = 1 << len(qubits)
    rho = [[F(0)] * d for _ in range(d)]
    rest = [q for q in range(nq) if q not in qubits]
    for m1, a1 in state.items():
        for m2, a2 in state.items():
            if all(((m1 >> r) & 1) == ((m2 >> r) & 1) for r in rest):
                i = sum(((m1 >> q) & 1) << t for t, q in enumerate(qubits))
                j = sum(((m2 >> q) & 1) << t for t, q in enumerate(qubits))
                rho[i][j] += a1 * a2
    return rho


mm = GA.mat_mul


def mtrace(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def purity(rho):
    d = len(rho)
    return sum((rho[i][j] * rho[j][i] for i in range(d) for j in range(d)), F(0))


def pinch(rho):
    """The descent E_N: complete dephasing in the joint number basis."""
    d = len(rho)
    return [[rho[i][j] if i == j else F(0) for j in range(d)] for i in range(d)]


def is_diag(rho):
    d = len(rho)
    return all(rho[i][j] == 0 for i in range(d) for j in range(d) if i != j)


def expect_xz(xs, zs, rho):
    """<prod_{i in xs} X_i prod_{j in zs} Z_j> against a density matrix (positions within its qubits)."""
    xmask = 0
    for i in xs:
        xmask ^= (1 << i)
    tot = F(0)
    for i in range(len(rho)):
        sign = 1
        for j in zs:
            if (i >> j) & 1:
                sign = -sign
        tot += rho[i ^ xmask][i] * sign
    return tot


def run_model(pairs, schedule, scramble=True):
    """The rate model: event t injects pair t (if any) and then evicts the oldest window qubits
    until |W| <= schedule[t], applying a controlled-Z between the two oldest window qubits before
    each eviction (number-diagonal scrambling). Returns stages [(state, radiation, window)]."""
    state = {0: F(1)}
    window, radiation, stages = [], [], []
    for t, cap in enumerate(schedule):
        if t < len(pairs):
            c, s = pairs[t]
            state = pair_state(c, s, t, state)
            radiation.append(2 * t)
            window.append(2 * t + 1)
        while len(window) > cap:
            if scramble and len(window) >= 2:
                state = apply_cz(window[0], window[1], state)
            radiation.append(window.pop(0))
        stages.append((dict(state), list(radiation), list(window)))
    return stages


def trace_cube(A):
    """tr A^3 with sparse rows."""
    rows = [[(j, x) for j, x in enumerate(r) if x != 0] for r in A]
    return sum((x * y * A[k][i] for i in range(len(A)) for j, x in rows[i] for k, y in rows[j]), F(0))

# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}


def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer (series.ln_bounds, memoised)."""
    if n not in _LNB:
        _LNB[n] = series.ln_bounds(n)
    return _LNB[n]


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

MODEL_PAIRS = [(F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(12, 13), F(5, 13))]
SPEC2 = [F(1, 2), F(1, 4), F(1, 6), F(1, 12)]
SPEC3 = [F(1, 4), F(1, 5), F(1, 6), F(1, 8), F(1, 10), F(1, 12), F(1, 15), F(1, 120)]
ROT2 = [(0b00, 0b11, F(3, 5), F(4, 5)), (0b01, 0b10, F(5, 13), F(12, 13))]
ROT3 = [(0b000, 0b011, F(3, 5), F(4, 5)), (0b101, 0b110, F(4, 5), F(-3, 5)),
        (0b000, 0b101, F(5, 13), F(12, 13)), (0b001, 0b010, F(8, 17), F(15, 17)),
        (0b100, 0b111, F(3, 5), F(4, 5)), (0b001, 0b111, F(4, 5), F(3, 5))]


def rotation(dim, rots):
    W = [[F(int(i == j)) for j in range(dim)] for i in range(dim)]
    for (a, b, c, s) in rots:
        G = [[F(int(i == j)) for j in range(dim)] for i in range(dim)]
        G[a][a], G[b][b], G[a][b], G[b][a] = c, c, -s, s
        W = mm(W, G)
    return W


def mixed(spec, rots):
    d = len(spec)
    W = rotation(d, rots)
    rho = [[sum((W[i][k] * spec[k] * W[j][k] for k in range(d)), F(0)) for j in range(d)] for i in range(d)]
    return rho, W


def mode_marginal(rho, k):
    out = [[F(0), F(0)], [F(0), F(0)]]
    for i in range(len(rho)):
        for j in range(len(rho)):
            if (i | (1 << k)) == (j | (1 << k)):
                out[(i >> k) & 1][(j >> k) & 1] += rho[i][j]
    return out


def nmodes(rho):
    return len(rho).bit_length() - 1


def model_final():
    stages = run_model(MODEL_PAIRS, [2, 2, 2, 2, 1, 0])
    state, rad, win = stages[-1]
    assert not win
    return marginal(sorted(rad), state, 8)


def two_pair():
    (c1, s1), (c2, s2) = MODEL_PAIRS[0], MODEL_PAIRS[1]
    st = apply_cz(1, 3, pair_state(c2, s2, 1, pair_state(c1, s1, 0, {0: F(1)})))
    return marginal([0, 1, 2, 3], st, 4)


def check_diagonal_marginals_pass_through_descent():
    states = [model_final(), two_pair(), mixed(SPEC2, ROT2)[0], mixed(SPEC3, ROT3)[0]]
    for rho in states:
        Er = pinch(rho)
        assert Er != rho
        for k in range(nmodes(rho)):
            mk = mode_marginal(rho, k)
            assert mk[0][1] == 0 and mk[1][0] == 0
            assert mode_marginal(Er, k) == mk
    # control: |+>|0> has a coherent mode-0 marginal, which E_N changes
    plus = [[F(1, 2), F(1, 2), F(0), F(0)], [F(1, 2), F(1, 2), F(0), F(0)],
            [F(0), F(0), F(0), F(0)], [F(0), F(0), F(0), F(0)]]
    assert mode_marginal(plus, 0) == [[F(1, 2), F(1, 2)], [F(1, 2), F(1, 2)]]
    assert mode_marginal(pinch(plus), 0) == [[F(1, 2), F(0)], [F(0), F(1, 2)]]


def total_correlation(rho, S_rho):
    tot = LogVec()
    for k in range(nmodes(rho)):
        mk = mode_marginal(rho, k)
        tot = tot + entropy([mk[0][0], mk[1][1]])
    return tot - S_rho


def check_deficit_is_total_correlation_drop_mixed():
    for spec, rots in ((SPEC2, ROT2), (SPEC3, ROT3)):
        assert sum(spec) == 1
        rho, W = mixed(spec, rots)
        d = len(rho)
        Er = pinch(rho)
        WtrW = mm(mm([list(r) for r in zip(*W)], rho), W)
        tr_rho_ln_rho = LogVec()
        for k in range(d):
            assert WtrW[k][k] == spec[k]
            tr_rho_ln_rho = tr_rho_ln_rho + LogVec.ln_rat(spec[k]) * WtrW[k][k]
        tr_rho_ln_Er = LogVec()
        for i in range(d):
            tr_rho_ln_Er = tr_rho_ln_Er + LogVec.ln_rat(Er[i][i]) * rho[i][i]
        D = tr_rho_ln_rho - tr_rho_ln_Er
        C_rho = total_correlation(rho, entropy(spec))
        C_Er = total_correlation(Er, entropy([Er[i][i] for i in range(d)]))
        assert D == C_rho - C_Er
        assert logvec_lt(LogVec(), D)


def check_pure_state_deficit_is_whole_descended_entropy():
    premise("singularity.deficit-theorem-cost-descent-exactly")
    for rho, want in ((model_final(), entropy([F(16, 25), F(9, 25)]) * 3 + entropy([F(144, 169), F(25, 169)])),
                      (two_pair(), entropy([F(16, 25), F(9, 25)]) * 2)):
        d = len(rho)
        assert mtrace(rho) == 1 and purity(rho) == 1
        Er = pinch(rho)
        S_Er = entropy([Er[i][i] for i in range(d)])
        D = S_Er - LogVec()                       # deficit theorem with S(rho) = 0
        assert D == total_correlation(rho, LogVec()) - total_correlation(Er, S_Er)
        assert D == want

singularity.deficit-theorem-cost-descent:
"""singularity.deficit-theorem-cost-descent-exactly: exact checks of the deficit theorem.

Four complete families of orthogonal projectors on R^4 (two qubits): the joint-number pinching E_N
(four coordinate projectors), the two parity blocks span{|00>,|11>}, span{|01>,|10>}, a rotated
rank-one family u_k u_k^T and a rotated pair of rank-two blocks, the rotations being rational
orthogonal matrices, products of Givens rotations at (3/5, 4/5).
(1) Each family is complete and orthogonal; E(x) = sum_k P_k x P_k is idempotent, trace preserving
    and Hilbert-Schmidt self-adjoint, tr(E(a) b) = tr(a E(b)), on generic rational a, b.
(2) The proof's key lemma, tr(rho f(E rho)) = tr(E(rho) f(E rho)), in moment form f(x) = x^m,
    m = 1..4, for every family on three density matrices with coherences; control: it fails for
    f(E rho) replaced by rho.
(3) The identity S(E rho) - S(rho) = D(rho || E rho) as an identity of formal logarithms (exact
    LogVecs) wherever both sides have rational spectra: mixed states rho = V diag(p) V^T under the
    rotated rank-one family (ln rho = V diag(ln p) V^T and ln E rho = sum_k ln q_k P_k, the traces
    taken by matrix products), pure states under all four families (the blocks of E rho are rank one),
    and the scrambled two-pair state of the model under E_N, where D = S(E_N rho) = 2 H(16/25).
    D > 0 (rigorous bounds) in every case with rho != E rho, and D = 0 for rho = E rho.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise  # noqa: F401 (the claim has no premises)

# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}
_DEN = 1 << 160


def _atanh_bounds(z, K=30):
    """Rational bounds on atanh z for 0 <= z <= 1/3."""
    zz = z * z
    term, part = z, F(0)
    for k in range(K):
        part += term / (2 * k + 1)
        term *= zz
    tail = term / ((2 * K + 1) * (1 - zz))
    return part, part + tail


def _out(lo, hi):
    return F((lo.numerator * _DEN) // lo.denominator, _DEN), \
        F(-((-hi.numerator * _DEN) // hi.denominator), _DEN)


def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer."""
    if n in _LNB:
        return _LNB[n]
    if n == 1:
        return F(0), F(0)
    l2lo, l2hi = _atanh_bounds(F(1, 3))
    l2lo, l2hi = 2 * l2lo, 2 * l2hi
    a = n.bit_length() - 1
    x = F(n, 1 << a)
    zlo, zhi = _atanh_bounds((x - 1) / (x + 1))
    res = _out(a * l2lo + 2 * zlo, a * l2hi + 2 * zhi)
    _LNB[n] = res
    return res


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

N4 = 4


def eye(n):
    return [[F(int(i == j)) for j in range(n)] for i in range(n)]


def madd(A, B, c=1):
    return [[A[i][j] + c * B[i][j] for j in range(len(A))] for i in range(len(A))]


def mmul(A, B):
    return GA.mat_mul(A, B)


def tr(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def transpose(A):
    return [list(r) for r in zip(*A)]


def givens(i, j, c, s):
    G = eye(N4)
    G[i][i], G[j][j], G[i][j], G[j][i] = c, c, -s, s
    return G


def outer(u, v):
    return [[x * y for y in v] for x in u]


U = mmul(mmul(givens(0, 1, F(3, 5), F(4, 5)), givens(2, 3, F(3, 5), F(4, 5))), givens(1, 2, F(4, 5), F(3, 5)))
V = mmul(givens(0, 2, F(4, 5), F(-3, 5)), givens(1, 3, F(3, 5), F(4, 5)))
COLS_U = [[U[i][k] for i in range(N4)] for k in range(N4)]


def coord(i):
    return [F(int(j == i)) for j in range(N4)]


FAMILIES = {
    "E_N": [outer(coord(i), coord(i)) for i in range(N4)],
    "parity": [madd(outer(coord(0), coord(0)), outer(coord(3), coord(3))),
               madd(outer(coord(1), coord(1)), outer(coord(2), coord(2)))],
    "rotated rank one": [outer(u, u) for u in COLS_U],
    "rotated rank two": [madd(outer(COLS_U[0], COLS_U[0]), outer(COLS_U[2], COLS_U[2])),
                         madd(outer(COLS_U[1], COLS_U[1]), outer(COLS_U[3], COLS_U[3]))],
}
A_GEN = [[F(1), F(2), F(3), F(4)], [F(5), F(6), F(7), F(8)],
         [F(9), F(1, 2), F(2, 3), F(3, 5)], [F(4, 7), F(1, 9), F(8, 3), F(11)]]
B_GEN = [[F(2), F(1), F(0), F(5)], [F(3), F(7), F(1, 3), F(2)],
         [F(1, 5), F(4), F(6), F(1)], [F(9), F(2, 7), F(3), F(8)]]
P_SPEC = [F(1, 2), F(1, 4), F(1, 6), F(1, 12)]
PSI = [[F(1, 2), F(1, 2), F(1, 2), F(1, 2)], [F(2, 7), F(3, 7), F(6, 7), F(0)],
       [F(1, 3), F(-2, 3), F(0), F(2, 3)]]


def E(fam, x):
    out = [[F(0)] * N4 for _ in range(N4)]
    for P in fam:
        out = madd(out, mmul(mmul(P, x), P))
    return out


def rho_mixed(W, spec):
    return mmul(mmul(W, [[spec[i] if i == j else F(0) for j in range(N4)] for i in range(N4)]),
                transpose(W))


def check_pinching_structure():
    for fam in FAMILIES.values():
        tot = [[F(0)] * N4 for _ in range(N4)]
        for a, P in enumerate(fam):
            tot = madd(tot, P)
            for b, Q in enumerate(fam):
                assert mmul(P, Q) == (P if a == b else [[F(0)] * N4 for _ in range(N4)])
        assert tot == eye(N4)
        EA, EB = E(fam, A_GEN), E(fam, B_GEN)
        assert E(fam, EA) == EA and EA != A_GEN
        assert tr(EA) == tr(A_GEN)
        assert tr(mmul(EA, B_GEN)) == tr(mmul(A_GEN, EB))


def check_key_lemma_moment_form():
    states = [rho_mixed(V, P_SPEC), rho_mixed(mmul(V, U), [F(3, 5), F(1, 5), F(1, 10), F(1, 10)]),
              outer(PSI[0], PSI[0])]
    for fam in FAMILIES.values():
        for rho in states:
            Er = E(fam, rho)
            assert tr(rho) == 1 and Er != rho
            Em = Er
            for m in range(1, 5):
                assert tr(mmul(rho, Em)) == tr(mmul(Er, Em))
                Em = mmul(Em, Er)
            assert tr(mmul(rho, rho)) != tr(mmul(Er, rho))


def check_entropy_identity_exact():
    # (a) mixed rho = V diag(p) V^T under the rotated rank-one family
    fam = FAMILIES["rotated rank one"]
    rho = rho_mixed(V, P_SPEC)
    Er = E(fam, rho)
    q = [tr(mmul(P, Er)) for P in fam]
    for P, qk in zip(fam, q):
        assert mmul(Er, P) == [[qk * x for x in row] for row in P]
    assert sum(q) == 1
    VtrV = mmul(mmul(transpose(V), rho), V)
    tr_rho_ln_rho = LogVec()
    for i in range(N4):
        tr_rho_ln_rho = tr_rho_ln_rho + LogVec.ln_rat(P_SPEC[i]) * VtrV[i][i]
    tr_rho_ln_Er = LogVec()
    for P, qk in zip(fam, q):
        tr_rho_ln_Er = tr_rho_ln_Er + LogVec.ln_rat(qk) * tr(mmul(rho, P))
    D = tr_rho_ln_rho - tr_rho_ln_Er
    assert D == entropy(q) - entropy(P_SPEC)
    assert logvec_lt(LogVec(), D)
    # rho = E rho: zero deficit
    rho0 = madd(madd(fam[0], fam[1], F(1, 3)), madd(fam[2], fam[3], F(1, 5)), F(1, 2))
    rho0 = [[x * F(15, 29) for x in row] for row in rho0]
    assert tr(rho0) == 1 and E(fam, rho0) == rho0
    # (b) pure states under every family: blocks of E rho are rank one with weight w_k
    for fam in FAMILIES.values():
        for psi in PSI:
            nrm = sum(x * x for x in psi)
            rho = [[x / nrm for x in row] for row in outer(psi, psi)]
            Er = E(fam, rho)
            w = [tr(mmul(P, rho)) for P in fam]
            tr_rho_ln_Er = LogVec()
            for P, wk in zip(fam, w):
                if wk == 0:
                    continue
                Pi = [[x / wk for x in row] for row in mmul(mmul(P, rho), P)]
                assert mmul(Pi, Pi) == Pi and mmul(Er, Pi) == [[wk * x for x in row] for row in Pi]
                tr_rho_ln_Er = tr_rho_ln_Er + LogVec.ln_rat(wk) * tr(mmul(rho, Pi))
            D = LogVec() - tr_rho_ln_Er
            assert D == entropy(w)
            assert (Er == rho) == (D == LogVec())
            if Er != rho:
                assert logvec_lt(LogVec(), D)
    # (c) the model's scrambled two-pair state under E_N: D = S(E_N rho) = 2 H(16/25)
    c, s = F(4, 5), F(3, 5)
    amp = {(b1, b2): (c if b1 == 0 else s) * (c if b2 == 0 else s) * (-1 if b1 and b2 else 1)
           for b1 in (0, 1) for b2 in (0, 1)}
    psi16 = [F(0)] * 16
    for (b1, b2), a in amp.items():
        psi16[b1 * 3 + b2 * 12] = a
    diag = [x * x for x in psi16]
    assert sorted(x for x in diag if x) == [F(81, 625), F(144, 625), F(144, 625), F(256, 625)]
    assert entropy(diag) == entropy([F(16, 25), F(9, 25)]) * 2

singularity.envelope-endpoint-why-bounda:
"""singularity.envelope-endpoint-why-boundary-mode-locality: exact checks of the envelope, the
endpoint, and the necessity of (L_E).

Exact amplitudes, qubits R_k = 2k, L_k = 2k+1; entropies are exact formal logarithms (LogVecs) of
rational spectra and inequalities are decided by rigorous rational bounds on ln p.
(1) Envelope and endpoint under number-diagonal (controlled-Z) window dynamics, on the model table's
    run and on a five-pair run with a decreasing schedule: S_R = S_L <= min(S_th, C) at every stage
    (S_R = S_L through equal trace moments where the radiation has at most six qubits) and S_R = 0 at
    complete evaporation.
(2) (L_E) cannot be dropped: two pairs (24/25, 7/25), the rotation |00> -> 3/5|00> + 4/5|11>,
    |11> -> -4/5|00> + 3/5|11> on (L_1, L_2) (orthogonal, changes L_1's and L_2's occupations, so not
    number diagonal), then L_1 evicted: rho_L2 = diag(5968/15625, 9657/15625), global purity holds
    (S_R = S_L through tr rho_R^m = tr rho_L^m, m = 2, 3), and S_R > S_th strictly. In bits S_R lies in
    (0.95, 0.97); S_th = 2 H(576/625) lies in (0.54, 0.56) nats, that is (0.78, 0.80) bits.
"""
from fractions import Fraction as F

import GA
import series
from tp_premise import premise

# --- exact multi-qubit simulator (states: dict {bitmask: amplitude}; qubit R_k = 2k, L_k = 2k+1) ---

def pair_state(c, s, k, state):
    """Tensor the thermofield pair c|00> + s|11> on (R_k, L_k) onto the state."""
    out = {}
    for m, a in state.items():
        out[m] = out.get(m, 0) + a * c
        m2 = m | (1 << (2 * k)) | (1 << (2 * k + 1))
        out[m2] = out.get(m2, 0) + a * s
    return {m: a for m, a in out.items() if a != 0}


def apply_cz(i, j, state):
    return {m: (-a if (m >> i) & 1 and (m >> j) & 1 else a) for m, a in state.items()}


def marginal(qubits, state, nq):
    """Reduced density matrix (unnormalised if the state is) over the listed qubits; bit t of the
    row index is the occupation of qubits[t]."""
    d = 1 << len(qubits)
    rho = [[F(0)] * d for _ in range(d)]
    rest = [q for q in range(nq) if q not in qubits]
    for m1, a1 in state.items():
        for m2, a2 in state.items():
            if all(((m1 >> r) & 1) == ((m2 >> r) & 1) for r in rest):
                i = sum(((m1 >> q) & 1) << t for t, q in enumerate(qubits))
                j = sum(((m2 >> q) & 1) << t for t, q in enumerate(qubits))
                rho[i][j] += a1 * a2
    return rho


mm = GA.mat_mul


def mtrace(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def purity(rho):
    d = len(rho)
    return sum((rho[i][j] * rho[j][i] for i in range(d) for j in range(d)), F(0))


def pinch(rho):
    """The descent E_N: complete dephasing in the joint number basis."""
    d = len(rho)
    return [[rho[i][j] if i == j else F(0) for j in range(d)] for i in range(d)]


def is_diag(rho):
    d = len(rho)
    return all(rho[i][j] == 0 for i in range(d) for j in range(d) if i != j)


def expect_xz(xs, zs, rho):
    """<prod_{i in xs} X_i prod_{j in zs} Z_j> against a density matrix (positions within its qubits)."""
    xmask = 0
    for i in xs:
        xmask ^= (1 << i)
    tot = F(0)
    for i in range(len(rho)):
        sign = 1
        for j in zs:
            if (i >> j) & 1:
                sign = -sign
        tot += rho[i ^ xmask][i] * sign
    return tot


def run_model(pairs, schedule, scramble=True):
    """The rate model: event t injects pair t (if any) and then evicts the oldest window qubits
    until |W| <= schedule[t], applying a controlled-Z between the two oldest window qubits before
    each eviction (number-diagonal scrambling). Returns stages [(state, radiation, window)]."""
    state = {0: F(1)}
    window, radiation, stages = [], [], []
    for t, cap in enumerate(schedule):
        if t < len(pairs):
            c, s = pairs[t]
            state = pair_state(c, s, t, state)
            radiation.append(2 * t)
            window.append(2 * t + 1)
        while len(window) > cap:
            if scramble and len(window) >= 2:
                state = apply_cz(window[0], window[1], state)
            radiation.append(window.pop(0))
        stages.append((dict(state), list(radiation), list(window)))
    return stages


def trace_cube(A):
    """tr A^3 with sparse rows."""
    rows = [[(j, x) for j, x in enumerate(r) if x != 0] for r in A]
    return sum((x * y * A[k][i] for i in range(len(A)) for j, x in rows[i] for k, y in rows[j]), F(0))

# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}


def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer (series.ln_bounds, memoised)."""
    if n not in _LNB:
        _LNB[n] = series.ln_bounds(n)
    return _LNB[n]


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

MODEL_PAIRS = [(F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(12, 13), F(5, 13))]
PAIRS_B = [(F(24, 25), F(7, 25)), (F(3, 5), F(4, 5)), (F(12, 13), F(5, 13)), (F(20, 29), F(21, 29)),
           (F(8, 17), F(15, 17))]
RUNS = [(MODEL_PAIRS, [2, 2, 2, 2, 1, 0]), (PAIRS_B, [3, 3, 3, 2, 2, 1, 1, 0])]
# Qubits per thermofield pair (R_k = 2k, L_k = 2k + 1).
QUBITS_PER_PAIR = 2
# Largest radiation (in qubits) whose dense marginal is built to compare tr rho^2 and tr rho^3.
MAX_RAD_QUBITS = 6
WITNESS = (F(24, 25), F(7, 25))
ROT = (F(3, 5), F(4, 5))


def check_envelope_and_endpoint_under_diagonal_dynamics():
    premise("singularity.eviction-window-thermal-product-radiation-entropy")
    premise("singularity.l-boundary-mode-locality")
    premise("singularity.rate-models-kinematic-inputs-l-u")
    ln2 = LogVec.ln_int(2)
    assert entropy([F(1, 2), F(1, 2)]) == ln2          # a qubit's capacity ln 2, attained when maximally mixed
    for pairs, schedule in RUNS:
        nq = QUBITS_PER_PAIR * len(pairs)
        stages = run_model(pairs, schedule)
        for t, (state, rad, win) in enumerate(stages):
            S_th = LogVec()
            for k in range(min(t + 1, len(pairs))):
                c, s = pairs[k]
                S_th = S_th + entropy([c * c, s * s])
            rL = marginal(sorted(win), state, nq)
            S_L = entropy([rL[i][i] for i in range(len(rL))])
            assert is_diag(rL)
            assert logvec_le(S_L, S_th) and logvec_le(S_L, ln2 * len(win))
            if len(win) == len(rad):
                # nothing evicted yet (one R radiated and one L in the window per injected pair, no
                # scrambling applied): the window is the L halves of a product of pairs, so the envelope
                # is attained, S_L = S_th
                assert S_L == S_th
            if len(rad) <= MAX_RAD_QUBITS:
                rR = marginal(sorted(rad), state, nq)
                assert purity(rR) == purity(rL) and trace_cube(rR) == trace_cube(rL)
        state, rad, win = stages[-1]
        assert win == [] and purity(marginal(sorted(rad), state, nq)) == 1


def witness_state():
    c, s = WITNESS
    co, si = ROT
    st = pair_state(c, s, 1, pair_state(c, s, 0, {0: F(1)}))
    both = (1 << 1) | (1 << 3)
    rot = {}
    for m, a in st.items():
        l1, l2 = (m >> 1) & 1, (m >> 3) & 1
        if (l1, l2) == (0, 0):
            rot[m] = rot.get(m, F(0)) + co * a
            rot[m | both] = rot.get(m | both, F(0)) + si * a
        elif (l1, l2) == (1, 1):
            rot[m & ~both] = rot.get(m & ~both, F(0)) - si * a
            rot[m] = rot.get(m, F(0)) + co * a
        else:
            rot[m] = rot.get(m, F(0)) + a
    return st, rot


def check_locality_premise_is_necessary():
    premise("singularity.l-boundary-mode-locality")
    st, rot = witness_state()
    assert sum(a * a for a in rot.values()) == 1
    # the rotation is not number diagonal: it moves weight between |00> and |11> of (L_1, L_2)
    assert any(((m >> 1) & 1) != ((m >> 0) & 1) for m in rot)
    rL = marginal([3], rot, 4)                      # window after evicting L_1: L_2 alone
    rR = marginal([0, 1, 2], rot, 4)                 # radiation: R_1, R_2 and the evicted L_1
    assert rL == [[F(5968, 15625), F(0)], [F(0), F(9657, 15625)]]
    assert purity(rR) == purity(rL) and trace_cube(rR) == trace_cube(rL)
    S_R = entropy([rL[0][0], rL[1][1]])
    c, s = WITNESS
    S_th = entropy([c * c, s * s]) * 2
    assert c * c == F(576, 625)
    assert logvec_lt(S_th, S_R)
    ln2 = LogVec.ln_int(2)
    assert logvec_lt(ln2 * F(95, 100), S_R) and logvec_lt(S_R, ln2 * F(97, 100))
    lo, hi = logvec_bounds(S_th)
    assert F(54, 100) < lo and hi < F(56, 100)
    assert logvec_lt(ln2 * F(78, 100), S_th) and logvec_lt(S_th, ln2 * F(80, 100))
    # without the rotation (number-diagonal dynamics) the same eviction stays inside the envelope
    rL0 = marginal([3], st, 4)
    assert rL0 == [[c * c, F(0)], [F(0), s * s]] and logvec_lt(entropy([c * c, s * s]), S_th)

singularity.eviction-window-thermal-prod:
"""singularity.eviction-window-thermal-product-radiation-entropy: exact checks of the eviction theorem.

The rate model is simulated on exact amplitudes (qubits R_k = 2k, L_k = 2k+1): event t injects pair
t (while pairs remain) and evicts the oldest window qubits down to the capacity schedule, with a
controlled-Z (number diagonal, (L_E)) between the two oldest window qubits before each eviction.
Three runs: the model table's run (four pairs, capacity 2, flush), a five-pair run with unequal angles
and a decreasing schedule 3,3,3,2,2,1,1,0, and the maximally entangled idealisation (amplitudes 1, 1,
normalised at the end) on the schedule 3,3,3,3,2,2,1,1,0. Entropies are exact formal logarithms
(LogVecs); inequalities use rigorous rational bounds on ln p.
(1) At every stage rho_L = tensor_{k in W} diag(c_k^2, s_k^2) entrywise, so S_L = sum_{W} h_k; the
    radiation and window have equal trace moments tr rho^m, m = 2, 3, where the radiation has at most
    six qubits (S_R = S_L), and the global state stays normalised.
(2) S_R <= min(S_th, C) at every stage and S_R = 0 at complete evaporation.
(3) Before the first eviction S_R = S_th exactly.
(4) S_R = C - sum_{W}(ln 2 - h_k) exactly at every stage; S_R < C strictly whenever the window is
    nonempty and no member has c = s; in the idealisation S_R = min(S_th, C) exactly at every stage.
"""
from fractions import Fraction as F

import GA
import series
from tp_premise import premise

# --- exact multi-qubit simulator (states: dict {bitmask: amplitude}; qubit R_k = 2k, L_k = 2k+1) ---

def pair_state(c, s, k, state):
    """Tensor the thermofield pair c|00> + s|11> on (R_k, L_k) onto the state."""
    out = {}
    for m, a in state.items():
        out[m] = out.get(m, 0) + a * c
        m2 = m | (1 << (2 * k)) | (1 << (2 * k + 1))
        out[m2] = out.get(m2, 0) + a * s
    return {m: a for m, a in out.items() if a != 0}


def apply_cz(i, j, state):
    return {m: (-a if (m >> i) & 1 and (m >> j) & 1 else a) for m, a in state.items()}


def marginal(qubits, state, nq):
    """Reduced density matrix (unnormalised if the state is) over the listed qubits; bit t of the
    row index is the occupation of qubits[t]."""
    d = 1 << len(qubits)
    rho = [[F(0)] * d for _ in range(d)]
    rest = [q for q in range(nq) if q not in qubits]
    for m1, a1 in state.items():
        for m2, a2 in state.items():
            if all(((m1 >> r) & 1) == ((m2 >> r) & 1) for r in rest):
                i = sum(((m1 >> q) & 1) << t for t, q in enumerate(qubits))
                j = sum(((m2 >> q) & 1) << t for t, q in enumerate(qubits))
                rho[i][j] += a1 * a2
    return rho


mm = GA.mat_mul


def mtrace(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def purity(rho):
    d = len(rho)
    return sum((rho[i][j] * rho[j][i] for i in range(d) for j in range(d)), F(0))


def pinch(rho):
    """The descent E_N: complete dephasing in the joint number basis."""
    d = len(rho)
    return [[rho[i][j] if i == j else F(0) for j in range(d)] for i in range(d)]


def is_diag(rho):
    d = len(rho)
    return all(rho[i][j] == 0 for i in range(d) for j in range(d) if i != j)


def expect_xz(xs, zs, rho):
    """<prod_{i in xs} X_i prod_{j in zs} Z_j> against a density matrix (positions within its qubits)."""
    xmask = 0
    for i in xs:
        xmask ^= (1 << i)
    tot = F(0)
    for i in range(len(rho)):
        sign = 1
        for j in zs:
            if (i >> j) & 1:
                sign = -sign
        tot += rho[i ^ xmask][i] * sign
    return tot


def run_model(pairs, schedule, scramble=True):
    """The rate model: event t injects pair t (if any) and then evicts the oldest window qubits
    until |W| <= schedule[t], applying a controlled-Z between the two oldest window qubits before
    each eviction (number-diagonal scrambling). Returns stages [(state, radiation, window)]."""
    state = {0: F(1)}
    window, radiation, stages = [], [], []
    for t, cap in enumerate(schedule):
        if t < len(pairs):
            c, s = pairs[t]
            state = pair_state(c, s, t, state)
            radiation.append(2 * t)
            window.append(2 * t + 1)
        while len(window) > cap:
            if scramble and len(window) >= 2:
                state = apply_cz(window[0], window[1], state)
            radiation.append(window.pop(0))
        stages.append((dict(state), list(radiation), list(window)))
    return stages


def trace_cube(A):
    """tr A^3 with sparse rows."""
    rows = [[(j, x) for j, x in enumerate(r) if x != 0] for r in A]
    return sum((x * y * A[k][i] for i in range(len(A)) for j, x in rows[i] for k, y in rows[j]), F(0))

# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}


def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer (series.ln_bounds, memoised)."""
    if n not in _LNB:
        _LNB[n] = series.ln_bounds(n)
    return _LNB[n]


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

MODEL_PAIRS = [(F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(12, 13), F(5, 13))]
PAIRS_B = [(F(24, 25), F(7, 25)), (F(3, 5), F(4, 5)), (F(12, 13), F(5, 13)), (F(20, 29), F(21, 29)),
           (F(8, 17), F(15, 17))]
IDEAL = [(F(1), F(1))] * 6
RUNS = [(MODEL_PAIRS, [2, 2, 2, 2, 1, 0]), (PAIRS_B, [3, 3, 3, 2, 2, 1, 1, 0]),
        (IDEAL, [3, 3, 3, 3, 2, 2, 1, 1, 0])]


def h(pair):
    c, s = pair
    n = c * c + s * s
    return entropy([c * c / n, s * s / n])


def stage_data(pairs, schedule):
    """Per stage: (normalised rho_L, rho_R or None, W members, S_th, number injected, evicted yet)."""
    nq = 2 * len(pairs)
    out = []
    for t, (state, rad, win) in enumerate(run_model(pairs, schedule)):
        norm = sum(a * a for a in state.values())
        rhoL = [[x / norm for x in row] for row in marginal(sorted(win), state, nq)]
        rhoR = None
        if len(rad) <= 6:
            rhoR = [[x / norm for x in row] for row in marginal(sorted(rad), state, nq)]
        injected = min(t + 1, len(pairs))
        S_th = LogVec()
        for k in range(injected):
            S_th = S_th + h(pairs[k])
        out.append((rhoL, rhoR, [q // 2 for q in sorted(win)], S_th, injected,
                    any(q % 2 for q in rad)))
    return out


def check_window_is_thermal_product():
    premise("singularity.rate-models-kinematic-inputs-l-u")
    premise("singularity.l-boundary-mode-locality")
    premise("singularity.no-attic-derived-model")
    for pairs, schedule in RUNS:
        data = stage_data(pairs, schedule)
        assert len(data) == len(schedule)
        for rhoL, rhoR, W, S_th, inj, ev in data:
            d = len(rhoL)
            assert d == 2 ** len(W) and is_diag(rhoL)
            S_W = LogVec()
            for idx in range(d):
                pr = F(1)
                for pos, k in enumerate(W):
                    c, s = pairs[k]
                    n = c * c + s * s
                    pr *= s * s / n if (idx >> pos) & 1 else c * c / n
                assert rhoL[idx][idx] == pr
            for k in W:
                S_W = S_W + h(pairs[k])
            assert entropy([rhoL[i][i] for i in range(d)]) == S_W
            if rhoR is not None:
                assert mtrace(rhoR) == 1 and mtrace(rhoL) == 1
                R2, L2 = mm(rhoR, rhoR), mm(rhoL, rhoL)
                assert mtrace(R2) == mtrace(L2) and mtrace(mm(R2, rhoR)) == mtrace(mm(L2, rhoL))


def check_envelope_endpoint_and_rising_branch():
    premise("singularity.rate-models-kinematic-inputs-l-u")
    ln2 = LogVec.ln_int(2)
    for (pairs, schedule), want_rising in zip(RUNS, (2, 3, 3)):
        data = stage_data(pairs, schedule)
        n_rising = 0
        for rhoL, rhoR, W, S_th, inj, evicted in data:
            S_R = entropy([rhoL[i][i] for i in range(len(rhoL))])
            C = ln2 * len(W)
            assert logvec_le(S_R, S_th) and logvec_le(S_R, C)
            if not evicted:
                n_rising += 1
                assert S_R == S_th and len(W) == inj
        rhoL = data[-1][0]
        assert data[-1][2] == [] and entropy([rhoL[i][i] for i in range(len(rhoL))]) == LogVec()
        assert n_rising == want_rising


def check_falling_branch_and_idealisation():
    ln2 = LogVec.ln_int(2)
    for pairs, schedule in RUNS:
        for rhoL, rhoR, W, S_th, inj, ev in stage_data(pairs, schedule):
            S_R = entropy([rhoL[i][i] for i in range(len(rhoL))])
            C = ln2 * len(W)
            short = LogVec()
            for k in W:
                short = short + (ln2 - h(pairs[k]))
            assert S_R == C - short
            maximal = all(pairs[k][0] == pairs[k][1] for k in W)
            assert (S_R == C) == maximal
            if W and not maximal:
                assert logvec_lt(S_R, C)
            if pairs is IDEAL:
                assert S_R == (S_th if logvec_le(S_th, C) else C)

singularity.imported-descent-one-way-con:
"""singularity.imported-descent-one-way-conditional-expectation: exact checks in Cl(p+1, q+1) (GA engine).

E is the pinching x -> PxP + (1-P)x(1-P), P = f^* f, f = (e+ + e-)/2, f^* = (e+ - e-)/2.
(1) For the six signatures with p + q <= 2: E is idempotent, unital, has image the commutant of P
    (dimension 2^(n+1)), fixes it pointwise and is a bimodule map over it: a conditional expectation.
(2) ker E = A f^* + A f (dimension 2^(n+1)), the adjoined ladder sector.
(3) No unital homomorphism B -> A: every Wedderburn block of B is larger than A (p + q <= 3).
(4) Uniqueness: for (p, q) = (0,0), (1,0), (0,1) the linear maps T : B -> B (all (dim B)^2 entries
    unknown) with T = id on the commutant C, T(B) in C, T(cx) = c T(x), T(xc) = T(x) c (c in a basis of C)
    and scalar part (normalised trace) preserved form an affine space of dimension 0, and E is its point.
    The trace condition is not needed for this finite case: the bimodule conditions alone already force
    T = E (also checked), which is the order-two instance the Fact cites.
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
from tp_premise import premise

SIGS = [(0, 0), (1, 0), (0, 1), (2, 0), (1, 1), (0, 2)]


def setup(p, q):
    """B = Cl(p+1, q+1): A's generators 0..n-1, e+ = n (square +1), e- = n+1 (square -1)."""
    n = p + q
    sq = GA.sig(p, q) + (1, -1)
    ep, em = GA.gen(n), GA.gen(n + 1)
    f = GA.scal(F(1, 2), GA.add(ep, em))
    fs = GA.scal(F(1, 2), GA.sub(ep, em))
    P = GA.mul(fs, f, sq)
    return n, sq, f, fs, P


def mul(sq, *xs):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, sq)
    return out


def pinch(x, P, sq):
    Q = GA.sub(GA.sc(1), P)
    return GA.add(mul(sq, P, x, P), mul(sq, Q, x, Q))


def rank(elems, m):
    rows = [GA.basis_vector_of(x, GA.all_blades(m)) for x in elems if x]
    return GA.rank_of_vectors(rows) if rows else 0


def blocks(sq, m):
    """Dimensions of the Wedderburn blocks of the (nondegenerate) Clifford algebra with squares sq."""
    cb = [b for b in GA.all_blades(m) if all(GA.commutes(GA.gen(i), {b: F(1)}, sq) for i in range(m))]
    if cb == [()]:
        return [2 ** m]
    om = {tuple(range(m)): F(1)}
    if GA.eq(GA.mul(om, om, sq), GA.sc(-1)):
        return [2 ** m]
    return [rank([GA.mul(GA.scal(F(1, 2), GA.add(GA.sc(1), GA.scal(s, om))), {b: F(1)}, sq)
                  for b in GA.all_blades(m)], m) for s in (1, -1)]


def comm_basis(n, sq, f, fs):
    """A + A f f^*: the A blades and their products with f f^*."""
    ffs = GA.mul(f, fs, sq)
    base = [{b: F(1)} for b in GA.all_blades(n)]
    return base + [GA.mul(a, ffs, sq) for a in base]


def check_pinching_is_conditional_expectation():
    premise("transport.pinching-kernel")
    ok = True
    for (p, q) in SIGS:
        n, sq, f, fs, P = setup(p, q)
        m_ = n + 2
        ok = ok and GA.mul(f, f, sq) == {} and GA.mul(fs, fs, sq) == {}
        ok = ok and GA.add(GA.mul(f, fs, sq), GA.mul(fs, f, sq)) == GA.sc(1)
        ok = ok and GA.mul(P, P, sq) == P
        imgs = []
        for b in GA.all_blades(m_):
            x = {b: F(1)}
            Ex = pinch(x, P, sq)
            ok = ok and pinch(Ex, P, sq) == Ex and GA.commutes(Ex, P, sq)
            imgs.append(Ex)
        ok = ok and pinch(GA.sc(1), P, sq) == GA.sc(1)
        ok = ok and rank(imgs, m_) == 2 ** (n + 1)
        comm = [GA.sub(GA.mul({b: F(1)}, P, sq), GA.mul(P, {b: F(1)}, sq)) for b in GA.all_blades(m_)]
        ok = ok and 2 ** m_ - rank(comm, m_) == 2 ** (n + 1)
        C = comm_basis(n, sq, f, fs)
        ok = ok and rank(C, m_) == 2 ** (n + 1) and all(pinch(c, P, sq) == c for c in C)
        if n <= 1:
            for c in C:
                for c2 in C:
                    for b in GA.all_blades(m_):
                        x = {b: F(1)}
                        ok = ok and pinch(mul(sq, c, x, c2), P, sq) == mul(sq, c, pinch(x, P, sq), c2)
        else:
            for c in C[:4]:
                for c2 in C[-4:]:
                    for b in GA.all_blades(m_):
                        x = {b: F(1)}
                        ok = ok and pinch(mul(sq, c, x, c2), P, sq) == mul(sq, c, pinch(x, P, sq), c2)
    GA.check("pinching: idempotent conditional expectation onto the commutant of P (dimension 2 dim A)", ok)
    return ok


def check_kernel_is_ladder_sector():
    premise("transport.pinching-kernel")
    ok = True
    for (p, q) in SIGS:
        n, sq, f, fs, P = setup(p, q)
        m_ = n + 2
        ladder = [GA.mul({b: F(1)}, y, sq) for b in GA.all_blades(n) for y in (f, fs)]
        ok = ok and all(pinch(x, P, sq) == {} for x in ladder)
        ok = ok and rank(ladder, m_) == 2 ** (n + 1)
        imgs = [pinch({b: F(1)}, P, sq) for b in GA.all_blades(m_)]
        ok = ok and 2 ** m_ - rank(imgs, m_) == 2 ** (n + 1)
        ok = ok and pinch(f, P, sq) == {} and pinch(fs, P, sq) == {}
    GA.check("ker E = A f^* + A f, of dimension 2 dim A; E(f) = E(f^*) = 0", ok)
    return ok


def check_no_return_homomorphism():
    premise("transport.door-one-way")
    ok = True
    nsplit = 0
    for n in range(0, 4):
        for p in range(n + 1):
            q = n - p
            sqB = GA.sig(p, q) + (1, -1)
            bl = blocks(sqB, n + 2)
            if len(bl) == 2:
                nsplit += 1
                ok = ok and bl == [2 * 2 ** n, 2 * 2 ** n]
            else:
                ok = ok and bl == [4 * 2 ** n]
            ok = ok and min(bl) > 2 ** n
    ok = ok and nsplit == 3                     # (1,0), (2,1), (0,3)
    for (p, q) in SIGS:
        n, sq, f, fs, P = setup(p, q)
        ok = ok and pinch(GA.mul(f, fs, sq), P, sq) == GA.mul(f, fs, sq)
        ok = ok and GA.mul(pinch(f, P, sq), pinch(fs, P, sq), sq) == {}
        Q = GA.sub(GA.sc(1), P)
        x, y = fs, f
        D = lambda z: mul(sq, P, z, P)
        defect = GA.sub(D(GA.mul(x, y, sq)), GA.mul(D(x), D(y), sq))
        ok = ok and defect == mul(sq, P, x, Q, y, P) and defect == P
    GA.check("blocks of B exceed dim A (no unital B -> A); the pinching and the corner read-out are not multiplicative", ok)
    return ok


def lin_T(x, d, blades, pos):
    """Symbolic T(x): {output blade index: {(i, j): coeff}} for unknown T_ij (coefficient of blade i in T(blade j))."""
    out = {}
    for b, c in x.items():
        j = pos[b]
        for i in range(d):
            get_or_set(out, i, {})[(i, j)] = out.get(i, {}).get((i, j), F(0)) + c
    return out


def lin_mul(c, form, sq, blades, pos, left):
    out = {}
    for i, lf in form.items():
        for cb, cc in c.items():
            if left:
                s, b = GA.blade_mul(cb, blades[i], sq)
            else:
                s, b = GA.blade_mul(blades[i], cb, sq)
            if s == 0:
                continue
            k = pos[b]
            tgt = get_or_set(out, k, {})
            for key, v in lf.items():
                tgt[key] = tgt.get(key, F(0)) + s * cc * v
    return out


def lin_sub(f1, f2):
    out = {}
    for src, sgn in ((f1, 1), (f2, -1)):
        for k, lf in src.items():
            tgt = get_or_set(out, k, {})
            for key, v in lf.items():
                tgt[key] = tgt.get(key, F(0)) + sgn * v
    return out


def solve_space(p, q, with_trace):
    n, sq, f, fs, P = setup(p, q)
    m_ = n + 2
    blades = GA.all_blades(m_)
    d = len(blades)
    pos = {b: i for i, b in enumerate(blades)}
    unknowns = [(i, j) for i in range(d) for j in range(d)]
    col = {u: k for k, u in enumerate(unknowns)}
    rows = []

    def add_forms(forms, rhs):
        for k in range(d):
            lf = forms.get(k, {})
            row = [F(0)] * (len(unknowns) + 1)
            for key, v in lf.items():
                row[col[key]] += v
            row[-1] = rhs.get(blades[k], F(0)) if rhs is not None else F(0)
            if any(row):
                rows.append(row)
    C = comm_basis(n, sq, f, fs)
    for c in C:
        add_forms(lin_T(c, d, blades, pos), c)                        # T(c) = c
    for b in blades:
        x = {b: F(1)}
        Tx = lin_T(x, d, blades, pos)
        add_forms(lin_sub(lin_mul(P, Tx, sq, blades, pos, False), lin_mul(P, Tx, sq, blades, pos, True)), None)
        for c in C:
            add_forms(lin_sub(lin_T(GA.mul(c, x, sq), d, blades, pos), lin_mul(c, Tx, sq, blades, pos, True)), None)
            add_forms(lin_sub(lin_T(GA.mul(x, c, sq), d, blades, pos), lin_mul(c, Tx, sq, blades, pos, False)), None)
        if with_trace:
            row = [F(0)] * (len(unknowns) + 1)
            row[col[(pos[()], pos[b])]] = F(1)
            row[-1] = F(1) if b == () else F(0)
            rows.append(row)
    A = [r[:-1] for r in rows]
    rk, rk_aug = GA.field_rank(A), GA.field_rank(rows)
    Emat = {}
    for j, b in enumerate(blades):
        for bb, v in pinch({b: F(1)}, P, sq).items():
            Emat[(pos[bb], j)] = v
    sat = all(sum(r[col[u]] * Emat.get(u, F(0)) for u in unknowns) == r[-1] for r in rows)
    return d * d - rk, rk == rk_aug, sat


# Signatures (p, q) at which the full linear system for T is solved (dim B = 4, 8, 8).
UNIQ_SIGS = [(0, 0), (1, 0), (0, 1)]


def check_trace_preserving_expectation_is_unique():
    ok = True
    dims = []
    for (p, q) in UNIQ_SIGS:
        for with_trace in (True, False):
            free, consistent, sat = solve_space(p, q, with_trace)
            dims.append(free)
            ok = ok and consistent and sat
    ok = ok and dims == [0] * (2 * len(UNIQ_SIGS))
    GA.check("the trace-preserving conditional expectation onto the commutant of P is unique and equals E", ok)
    return ok

singularity.models-entropy-sequence-exac:
"""singularity.models-entropy-sequence-exactly: exact checks of the model run's entropy sequence.

The run of the model table: pairs (4/5, 3/5) three times then (12/13, 5/13), window capacity two,
a controlled-Z between the two oldest window qubits before each eviction, and a final flush (six
stages). Exact rational amplitudes; entropies are exact formal logarithms (LogVecs); inequalities
are decided by rigorous rational bounds on ln 2, ln 3, ln 5, ln 13.
(1) At every stage rho_L is diagonal in the number basis with the product distribution of its
    members; S_L = sum_{k in W} H(c_k^2) exactly; tr rho_R^2 = prod_{k in W}(c_k^4 + s_k^4), the
    printed sequence 337/625, (337/625)^2, (337/625)^2, (337/625)(21361/28561), 21361/28561, 1; the
    global state is a unit vector at every stage. S_R = S_L because rho_R and rho_L have the same
    nonzero spectrum, computed at every stage (all six, up to eight radiation qubits): for each
    window configuration j the radiation vector v_j (the amplitudes with window part j) satisfies
    rho_R v_j = p_j v_j with p_j the j-th diagonal entry of rho_L, the v_j are mutually orthogonal
    with |v_j|^2 = p_j, and sum_j p_j = tr rho_R, so (rho_R being positive) every other eigenvalue
    of rho_R is 0.
(2) Phase I (events 1 and 2, no eviction yet): S_R = S_th exactly. Phase II (the three later stages
    with a nonempty window): S_R <= S_th and S_R < C = |W| ln 2 strictly, since no pair is maximally
    entangled. Completion: S_R = 0 and tr rho_R^2 = 1. Here S_R is computed as the entropy of the
    rho_L spectrum, which (1) shows is the nonzero spectrum of rho_R.
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
import series
from tp_premise import premise

# --- exact multi-qubit simulator (states: dict {bitmask: amplitude}; qubit R_k = 2k, L_k = 2k+1) ---

def pair_state(c, s, k, state):
    """Tensor the thermofield pair c|00> + s|11> on (R_k, L_k) onto the state."""
    out = {}
    for m, a in state.items():
        out[m] = out.get(m, 0) + a * c
        m2 = m | (1 << (2 * k)) | (1 << (2 * k + 1))
        out[m2] = out.get(m2, 0) + a * s
    return {m: a for m, a in out.items() if a != 0}


def apply_cz(i, j, state):
    return {m: (-a if (m >> i) & 1 and (m >> j) & 1 else a) for m, a in state.items()}


def marginal(qubits, state, nq):
    """Reduced density matrix (unnormalised if the state is) over the listed qubits; bit t of the
    row index is the occupation of qubits[t]."""
    d = 1 << len(qubits)
    rho = [[F(0)] * d for _ in range(d)]
    rest = [q for q in range(nq) if q not in qubits]
    for m1, a1 in state.items():
        for m2, a2 in state.items():
            if all(((m1 >> r) & 1) == ((m2 >> r) & 1) for r in rest):
                i = sum(((m1 >> q) & 1) << t for t, q in enumerate(qubits))
                j = sum(((m2 >> q) & 1) << t for t, q in enumerate(qubits))
                rho[i][j] += a1 * a2
    return rho


def mtrace(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def purity(rho):
    d = len(rho)
    return sum((rho[i][j] * rho[j][i] for i in range(d) for j in range(d)), F(0))


def pinch(rho):
    """The descent E_N: complete dephasing in the joint number basis."""
    d = len(rho)
    return [[rho[i][j] if i == j else F(0) for j in range(d)] for i in range(d)]


def is_diag(rho):
    d = len(rho)
    return all(rho[i][j] == 0 for i in range(d) for j in range(d) if i != j)


def expect_xz(xs, zs, rho):
    """<prod_{i in xs} X_i prod_{j in zs} Z_j> against a density matrix (positions within its qubits)."""
    xmask = 0
    for i in xs:
        xmask ^= (1 << i)
    tot = F(0)
    for i in range(len(rho)):
        sign = 1
        for j in zs:
            if (i >> j) & 1:
                sign = -sign
        tot += rho[i ^ xmask][i] * sign
    return tot


def run_model(pairs, schedule, scramble=True):
    """The rate model: event t injects pair t (if any) and then evicts the oldest window qubits
    until |W| <= schedule[t], applying a controlled-Z between the two oldest window qubits before
    each eviction (number-diagonal scrambling). Returns stages [(state, radiation, window)]."""
    state = {0: F(1)}
    window, radiation, stages = [], [], []
    for t, cap in enumerate(schedule):
        if t < len(pairs):
            c, s = pairs[t]
            state = pair_state(c, s, t, state)
            radiation.append(2 * t)
            window.append(2 * t + 1)
        while len(window) > cap:
            if scramble and len(window) >= 2:
                state = apply_cz(window[0], window[1], state)
            radiation.append(window.pop(0))
        stages.append((dict(state), list(radiation), list(window)))
    return stages



# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}


def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer (series.ln_bounds, memoised)."""
    if n not in _LNB:
        _LNB[n] = series.ln_bounds(n)
    return _LNB[n]


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

MODEL_PAIRS = [(F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(12, 13), F(5, 13))]
SCHEDULE = [2, 2, 2, 2, 1, 0]
NQ = 8


def H(c):
    return entropy([c * c, 1 - c * c])


def check_window_product_and_entropy_identity():
    premise("singularity.parity-protection")
    stages = run_model(MODEL_PAIRS, SCHEDULE)
    want_purity = [F(337, 625), F(337, 625) ** 2, F(337, 625) ** 2,
                   F(337, 625) * F(21361, 28561), F(21361, 28561), F(1)]
    assert len(stages) == len(want_purity)
    for (state, rad, win), wp in zip(stages, want_purity):
        assert sum(a * a for a in state.values()) == 1
        members = [q // 2 for q in sorted(win)]
        S_sum, pur = LogVec(), F(1)
        for k in members:
            c, s = MODEL_PAIRS[k]
            S_sum = S_sum + H(c)
            pur *= c ** 4 + s ** 4
        assert pur == wp
        rhoL = marginal(sorted(win), state, NQ)
        assert is_diag(rhoL)
        spec = [rhoL[i][i] for i in range(len(rhoL))]
        for idx in range(len(spec)):
            pr = F(1)
            for pos, k in enumerate(members):
                c, s = MODEL_PAIRS[k]
                pr *= s * s if (idx >> pos) & 1 else c * c
            assert spec[idx] == pr
        assert entropy(spec) == S_sum
        rad_s = sorted(rad)
        rhoR = marginal(rad_s, state, NQ)
        assert purity(rhoR) == wp
        # nonzero spectrum of rho_R: the radiation vectors v_j, one per window configuration j
        vs = {}
        for m, a in state.items():
            i = sum(((m >> q) & 1) << t for t, q in enumerate(rad_s))
            j = sum(((m >> q) & 1) << t for t, q in enumerate(sorted(win)))
            v = get_or_set(vs, j, {})
            v[i] = v.get(i, F(0)) + a
        assert sorted(vs) == [j for j in range(len(spec)) if spec[j] != 0]
        rows = [[(c, x) for c, x in enumerate(r) if x != 0] for r in rhoR]
        for j, v in vs.items():
            assert sum(x * x for x in v.values()) == spec[j]
            for i in range(len(rhoR)):
                assert sum((x * v.get(c, 0) for c, x in rows[i]), F(0)) == spec[j] * v.get(i, 0)
            for j2, v2 in vs.items():
                if j2 != j:
                    assert sum((x * v2.get(i, 0) for i, x in v.items()), F(0)) == 0
        assert sum(spec[j] for j in vs) == mtrace(rhoR) == 1


def check_phase_one_two_and_completion():
    premise("singularity.parity-protection")
    stages = run_model(MODEL_PAIRS, SCHEDULE)
    ln2 = LogVec.ln_int(2)
    n_phase1 = n_phase2 = n_end = 0
    for t, (state, rad, win) in enumerate(stages):
        injected = min(t + 1, len(MODEL_PAIRS))
        S_th = LogVec()
        for k in range(injected):
            S_th = S_th + H(MODEL_PAIRS[k][0])
        rhoL = marginal(sorted(win), state, NQ)
        S_R = entropy([rhoL[i][i] for i in range(len(rhoL))])
        C = ln2 * len(win)
        if all(q % 2 == 0 for q in rad):          # no eviction yet
            n_phase1 += 1
            assert S_R == S_th
        elif win:
            n_phase2 += 1
            assert logvec_le(S_R, S_th) and logvec_lt(S_R, C)
            assert S_R != S_th
        else:
            n_end += 1
            assert S_R == LogVec() and purity(marginal(sorted(rad), state, NQ)) == 1
    assert (n_phase1, n_phase2, n_end) == (2, 3, 1)

singularity.no-attic-derived-model:
"""singularity.no-attic-derived-model: exact checks that the model's kinematics leave no attic.

Rate-model runs on exact amplitudes (qubits R_k = 2k, L_k = 2k+1), controlled-Z scrambling before each
eviction: the model table's run (four pairs, capacity 2, flush) and a five-pair run on the schedule
3,3,2,2,1,1,0 with unequal angles.
(1) Kinematics: at every stage W(t) and R(t) are disjoint and together are exactly the 2 x (number
    injected) qubits; every eviction moves one qubit from W to R and none leaves the two sectors.
(2) Dynamics: the global state on R u L stays normalised (pure), and the two sectors' nonzero spectra
    agree at every stage of both runs (up to ten radiation qubits): rho_L is diagonal, and for each
    window configuration j the radiation vector v_j (the amplitudes with window part j) is an
    eigenvector of rho_R with eigenvalue the j-th diagonal entry p_j of rho_L; the v_j are mutually
    orthogonal with |v_j|^2 = p_j and sum_j p_j = tr rho_R = 1, so (rho_R being positive) every
    other eigenvalue is 0. No q-number content is held outside L u R.
(3) At each eviction the evicted qubit L_j is diag(c_j^2, s_j^2), and its complement in R u L has
    nonzero spectrum exactly {c_j^2, s_j^2} (computed as in (2)); with the global state pure, the
    mutual information I(L_j : rest) = S(L_j) + S(rest) - S(R u L), assembled as a formal
    combination of entropies of computed spectra, is 2 H(c_j^2) = 2 h_j: all of the evicted
    qubit's correlation sits inside L(t) u R(t).
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
from tp_premise import premise

# --- exact multi-qubit simulator (states: dict {bitmask: amplitude}; qubit R_k = 2k, L_k = 2k+1) ---

def pair_state(c, s, k, state):
    """Tensor the thermofield pair c|00> + s|11> on (R_k, L_k) onto the state."""
    out = {}
    for m, a in state.items():
        out[m] = out.get(m, 0) + a * c
        m2 = m | (1 << (2 * k)) | (1 << (2 * k + 1))
        out[m2] = out.get(m2, 0) + a * s
    return {m: a for m, a in out.items() if a != 0}


def apply_cz(i, j, state):
    return {m: (-a if (m >> i) & 1 and (m >> j) & 1 else a) for m, a in state.items()}


def marginal(qubits, state, nq):
    """Reduced density matrix (unnormalised if the state is) over the listed qubits; bit t of the
    row index is the occupation of qubits[t]."""
    d = 1 << len(qubits)
    rho = [[F(0)] * d for _ in range(d)]
    rest = [q for q in range(nq) if q not in qubits]
    for m1, a1 in state.items():
        for m2, a2 in state.items():
            if all(((m1 >> r) & 1) == ((m2 >> r) & 1) for r in rest):
                i = sum(((m1 >> q) & 1) << t for t, q in enumerate(qubits))
                j = sum(((m2 >> q) & 1) << t for t, q in enumerate(qubits))
                rho[i][j] += a1 * a2
    return rho


def mtrace(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def purity(rho):
    d = len(rho)
    return sum((rho[i][j] * rho[j][i] for i in range(d) for j in range(d)), F(0))


def pinch(rho):
    """The descent E_N: complete dephasing in the joint number basis."""
    d = len(rho)
    return [[rho[i][j] if i == j else F(0) for j in range(d)] for i in range(d)]


def is_diag(rho):
    d = len(rho)
    return all(rho[i][j] == 0 for i in range(d) for j in range(d) if i != j)


def expect_xz(xs, zs, rho):
    """<prod_{i in xs} X_i prod_{j in zs} Z_j> against a density matrix (positions within its qubits)."""
    xmask = 0
    for i in xs:
        xmask ^= (1 << i)
    tot = F(0)
    for i in range(len(rho)):
        sign = 1
        for j in zs:
            if (i >> j) & 1:
                sign = -sign
        tot += rho[i ^ xmask][i] * sign
    return tot


def run_model(pairs, schedule, scramble=True):
    """The rate model: event t injects pair t (if any) and then evicts the oldest window qubits
    until |W| <= schedule[t], applying a controlled-Z between the two oldest window qubits before
    each eviction (number-diagonal scrambling). Returns stages [(state, radiation, window)]."""
    state = {0: F(1)}
    window, radiation, stages = [], [], []
    for t, cap in enumerate(schedule):
        if t < len(pairs):
            c, s = pairs[t]
            state = pair_state(c, s, t, state)
            radiation.append(2 * t)
            window.append(2 * t + 1)
        while len(window) > cap:
            if scramble and len(window) >= 2:
                state = apply_cz(window[0], window[1], state)
            radiation.append(window.pop(0))
        stages.append((dict(state), list(radiation), list(window)))
    return stages


def nonzero_spectrum(diag_side, other_side, state, nq):
    """Nonzero spectrum of the marginal on other_side, for a pure state whose marginal on diag_side
    is diagonal: returns (rho_other, {j: p_j}) after asserting that each vector v_j (amplitudes with
    diag_side part j, indexed by the other_side configuration) satisfies rho_other v_j = p_j v_j,
    that the v_j are mutually orthogonal with |v_j|^2 = p_j, and that sum_j p_j = tr rho_other."""
    rd = marginal(diag_side, state, nq)
    assert is_diag(rd)
    ro = marginal(other_side, state, nq)
    vs = {}
    for m, a in state.items():
        i = sum(((m >> q) & 1) << t for t, q in enumerate(other_side))
        j = sum(((m >> q) & 1) << t for t, q in enumerate(diag_side))
        v = get_or_set(vs, j, {})
        v[i] = v.get(i, F(0)) + a
    spec = {j: rd[j][j] for j in vs}
    assert sorted(vs) == [j for j in range(len(rd)) if rd[j][j] != 0]
    rows = [[(c, x) for c, x in enumerate(r) if x != 0] for r in ro]
    for j, v in vs.items():
        assert sum(x * x for x in v.values()) == spec[j]
        for i in range(len(ro)):
            assert sum((x * v.get(c, 0) for c, x in rows[i]), F(0)) == spec[j] * v.get(i, 0)
        for j2, v2 in vs.items():
            if j2 != j:
                assert sum((x * v2.get(i, 0) for i, x in v.items()), F(0)) == 0
    assert sum(spec.values()) == mtrace(ro)
    return ro, spec


def spectrum_key(probs):
    """The entropy -sum p ln p of a spectrum as a formal symbol: its sorted nonzero eigenvalues;
    the zero entropy (a single eigenvalue 1) is the empty key."""
    key = tuple(sorted(p for p in probs if p != 0))
    return () if key == (F(1),) else key


def entropy_combination(terms):
    """A formal integer combination sum_i n_i S(spec_i), as {key: n} with zero entries dropped."""
    out = {}
    for n, probs in terms:
        k = spectrum_key(probs)
        if k:
            out[k] = out.get(k, 0) + n
    return {k: n for k, n in out.items() if n != 0}


MODEL_PAIRS = [(F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(12, 13), F(5, 13))]
PAIRS_B = [(F(24, 25), F(7, 25)), (F(3, 5), F(4, 5)), (F(12, 13), F(5, 13)), (F(20, 29), F(21, 29)),
           (F(8, 17), F(15, 17))]
RUNS = [(MODEL_PAIRS, [2, 2, 2, 2, 1, 0]), (PAIRS_B, [3, 3, 2, 2, 1, 1, 0])]


def check_two_sectors_exhaust_the_qubits():
    premise("singularity.rate-models-kinematic-inputs-l-u")
    for (pairs, schedule), want_evictions in zip(RUNS, (4, 5)):
        prev_rad, prev_win, evictions = [], [], 0
        for t, (state, rad, win) in enumerate(run_model(pairs, schedule)):
            inj = min(t + 1, len(pairs))
            assert not set(rad) & set(win)
            assert sorted(rad + win) == list(range(2 * inj))
            moved = [q for q in prev_win if q in rad]
            evictions += len(moved)
            assert all(q % 2 == 1 for q in moved)
            assert set(prev_rad) <= set(rad)
            prev_rad, prev_win = rad, win
        assert evictions == want_evictions


def check_sector_spectra_agree():
    premise("singularity.rate-models-kinematic-inputs-l-u")
    n_stages = 0
    for pairs, schedule in RUNS:
        nq = 2 * len(pairs)
        for state, rad, win in run_model(pairs, schedule):
            n_stages += 1
            assert sum(a * a for a in state.values()) == 1
            rR, spec = nonzero_spectrum(sorted(win), sorted(rad), state, nq)
            rL = marginal(sorted(win), state, nq)
            assert mtrace(rR) == mtrace(rL) == 1
            assert sorted(spec.values()) == sorted(rL[i][i] for i in range(len(rL)) if rL[i][i] != 0)
    assert n_stages == 13


def check_evicted_correlations_stay_in_the_sectors():
    n_evicted = 0
    for pairs, schedule in RUNS:
        nq = 2 * len(pairs)
        prev_win = []
        for state, rad, win in run_model(pairs, schedule):
            for q in [q for q in prev_win if q in rad]:
                n_evicted += 1
                c, s = pairs[q // 2]
                rq = marginal([q], state, nq)
                assert rq == [[c * c, F(0)], [F(0), s * s]]
                rest = [x for x in sorted(rad + win) if x != q]
                rr, spec = nonzero_spectrum([q], rest, state, nq)
                assert sorted(spec.values()) == sorted([c * c, s * s])
                assert purity(rr) == purity(rq) == c ** 4 + s ** 4
                # I(L_j : rest) = S(L_j) + S(rest) - S(R u L); the global state is a unit vector
                mi = entropy_combination([(1, [c * c, s * s]), (1, spec.values()), (-1, [F(1)])])
                assert mi == {tuple(sorted([c * c, s * s])): 2}
            prev_win = win
    assert n_evicted == 9

singularity.parity-protection:
"""singularity.parity-protection: exact checks of parity protection in the finite-ledger model.

The model is simulated on exact amplitudes (Gaussian rationals, GA.QI), qubits R_k = 2k, L_k = 2k+1.
Pairs c_k|00> + s_k|11> are injected one per event; before each eviction an arbitrary
number-basis-diagonal window unitary is applied, drawn from a program of diagonal gates: controlled-Z,
single-qubit phases (3+4i)/5 and (5-12i)/13, a controlled phase (8+15i)/17, a controlled-controlled-Z,
and sign flips. Four programs over two pair lists (four and five pairs, unequal angles).
(1) At every stage every single-qubit reduced density matrix, radiation or window, early or evicted,
    is exactly diag(c_k^2, s_k^2), coherence zero.
(2) The mechanism of the proof: the support constraint R_k = L_k holds in every configuration at
    every stage, and each configuration's squared modulus is the product of its pairs' populations.
(3) Controls showing the hypothesis does work: a hopping rotation (cos, sin) = (3/5, 4/5) between L_1
    and L_2, which is not number diagonal, moves the L_1 population from 9/25 to 23689/105625; the
    pairing rotation |00> -> 3/5|00> + 4/5|11> on (L_1, L_2) at (c, s) = (24/25, 7/25) moves the L_2
    marginal to diag(5968/15625, 9657/15625).
"""
from fractions import Fraction as F

import GA
from tp_premise import premise  # noqa: F401 (no premises: the claim has none)

QI = GA.QI
PAIRS_A = [(F(4, 5), F(3, 5)), (F(12, 13), F(5, 13)), (F(3, 5), F(4, 5)), (F(15, 17), F(8, 17))]
PAIRS_B = [(F(24, 25), F(7, 25)), (F(4, 5), F(3, 5)), (F(20, 29), F(21, 29)), (F(5, 13), F(12, 13)),
           (F(4, 5), F(3, 5))]
PH1, PH2, PH3 = QI(F(3, 5), F(4, 5)), QI(F(5, 13), F(-12, 13)), QI(F(8, 17), F(15, 17))
# diagonal gates on window positions: (kind, positions, phase)
PROGRAMS = [
    [("cz", (0, 1), None)],
    [("ph", (0,), PH1), ("cp", (0, 1), PH3), ("ph", (1,), PH2)],
    [("ccz", (0, 1, 2), None), ("cz", (0, 2), None), ("ph", (2,), PH2), ("flip", (1,), None)],
    [("cp", (1, 0), PH1), ("ccz", (0, 1, 2), None), ("ph", (0,), PH3)],
]
CAPS = [2, 3, 3, 2]


def apply_diag(gate, window, state):
    kind, pos, z = gate
    qs = [window[p] for p in pos if p < len(window)]
    if len(qs) < len(pos):
        return state
    out = {}
    for m, a in state.items():
        on = all((m >> q) & 1 for q in qs)
        if kind in ("cz", "ccz", "flip"):
            out[m] = -a if on else a
        else:
            out[m] = a * z if on else a
    return out


def run(pairs, cap, program):
    """Inject, scramble with the diagonal program, evict down to cap; flush at the end."""
    state = {0: QI(1)}
    window, radiation, stages = [], [], []

    def evict():
        nonlocal state
        for gate in program:
            state = apply_diag(gate, window, state)
        radiation.append(window.pop(0))

    for k, (c, s) in enumerate(pairs):
        new = {}
        for m, a in state.items():
            new[m] = a * c
            new[m | (1 << (2 * k)) | (1 << (2 * k + 1))] = a * s
        state = new
        radiation.append(2 * k)
        window.append(2 * k + 1)
        while len(window) > cap:
            evict()
        stages.append((dict(state), list(radiation), list(window)))
    while window:
        evict()
        stages.append((dict(state), list(radiation), list(window)))
    return stages


def single_marginal(q, state):
    """2x2 reduced density matrix of qubit q (complex amplitudes)."""
    rho = [[QI(0), QI(0)], [QI(0), QI(0)]]
    for m1, a1 in state.items():
        for m2, a2 in state.items():
            if (m1 | (1 << q)) == (m2 | (1 << q)):
                rho[(m1 >> q) & 1][(m2 >> q) & 1] += a1 * a2.conj()
    return rho


def check_every_single_qubit_marginal_is_thermal():
    for pairs in (PAIRS_A, PAIRS_B):
        for cap, program in zip(CAPS, PROGRAMS):
            stages = run(pairs, cap, program)
            assert len(stages) == len(pairs) + min(cap, len(pairs))
            for state, rad, win in stages:
                assert sorted(rad + win) == list(range(2 * ((len(rad) + len(win)) // 2)))
                for q in rad + win:
                    c, s = pairs[q // 2]
                    rho = single_marginal(q, state)
                    assert rho[0][0] == c * c and rho[1][1] == s * s
                    assert rho[0][1] == 0 and rho[1][0] == 0


def check_support_constraint_and_populations():
    for pairs in (PAIRS_A, PAIRS_B):
        n = len(pairs)
        for cap, program in zip(CAPS, PROGRAMS):
            for state, rad, win in run(pairs, cap, program):
                nk = (len(rad) + len(win)) // 2
                assert len(state) == 2 ** nk
                for m, a in state.items():
                    assert all(((m >> (2 * k)) & 1) == ((m >> (2 * k + 1)) & 1) for k in range(n))
                    w = F(1)
                    for k in range(nk):
                        c, s = pairs[k]
                        w *= s * s if (m >> (2 * k)) & 1 else c * c
                    assert (a * a.conj()) == QI(w)


def check_non_diagonal_unitaries_break_protection():
    # hopping rotation between L_1 (qubit 1) and L_2 (qubit 3): |10> -> c|10> + s|01>, |01> -> c|01> - s|10>
    (c1, s1), (c2, s2) = PAIRS_A[0], PAIRS_A[1]
    co, si = F(3, 5), F(4, 5)
    st = {0: F(1)}
    for k, (c, s) in enumerate(((c1, s1), (c2, s2))):
        new = {}
        for m, a in st.items():
            new[m] = a * c
            new[m | (1 << (2 * k)) | (1 << (2 * k + 1))] = a * s
        st = new
    hop = {}
    for m, a in st.items():
        l1, l2 = (m >> 1) & 1, (m >> 3) & 1
        if l1 != l2:
            flip = m ^ (1 << 1) ^ (1 << 3)
            hop[m] = hop.get(m, F(0)) + co * a
            hop[flip] = hop.get(flip, F(0)) + (si if l1 else -si) * a
        else:
            hop[m] = hop.get(m, F(0)) + a
    p1 = sum((a * a for m, a in hop.items() if (m >> 1) & 1), F(0))
    assert sum((a * a for a in hop.values()), F(0)) == 1
    assert s1 * s1 == F(9, 25) and p1 == F(23689, 105625)
    # pairing rotation on (L_1, L_2) at (c, s) = (24/25, 7/25), then L_2's marginal
    c, s = PAIRS_B[0]
    st = {0: F(1)}
    for k in range(2):
        new = {}
        for m, a in st.items():
            new[m] = a * c
            new[m | (1 << (2 * k)) | (1 << (2 * k + 1))] = a * s
        st = new
    rot = {}
    both = (1 << 1) | (1 << 3)
    for m, a in st.items():
        l1, l2 = (m >> 1) & 1, (m >> 3) & 1
        if (l1, l2) == (0, 0):
            rot[m] = rot.get(m, F(0)) + co * a
            rot[m | both] = rot.get(m | both, F(0)) + si * a
        elif (l1, l2) == (1, 1):
            rot[m & ~both] = rot.get(m & ~both, F(0)) - si * a
            rot[m] = rot.get(m, F(0)) + co * a
        else:
            rot[m] = rot.get(m, F(0)) + a
    p_empty = sum((a * a for m, a in rot.items() if not (m >> 3) & 1), F(0))
    assert c * c == F(576, 625) and p_empty == F(5968, 15625) and 1 - p_empty == F(9657, 15625)

singularity.two-levels-finite-model:
"""singularity.two-levels-finite-model: exact checks of the two ledgers on the full model run.

The full run: four pairs (4/5, 3/5) x 3 and (12/13, 5/13), capacity two, controlled-Z scrambling
before each eviction, final flush; rho_R(t) the radiation state at each stage (exact rationals),
rho_R the complete radiation (all eight qubits), E the joint-number pinching. Entropies are exact
formal logarithms; inequalities use rigorous rational bounds.
(1) tr rho_R^2 = 1; tr (E rho_R)^2 = prod_k (c_k^4 + s_k^4) = 817544276833/6972900390625;
    S_2(E rho_R) = log_2 of the inverse lies in (3.08, 3.10) bits; S(E rho_R) = sum_k H(c_k^2) = S_th.
    Stage by stage S(E rho_R(t)) is non-decreasing and tr (E rho_R(t))^2 non-increasing, while the
    ascended entropy S(rho_R(t)) = S(rho_L(t)) rises and returns to 0; pinching never raises purity.
(2) D(rho_R || E rho_R) = S(E rho_R) - S(rho_R) = S_th; every single-qubit marginal is identical at
    the two levels; the decoding correlators (<X_R1 X_L1>, <X_R1 X_L1 Z_L2>) of the scrambled and the
    unscrambled two-pair histories, (168/625, 24/25) and (24/25, 168/625), become (0, 0) under E in
    both; the parity average (rho + Gamma rho Gamma)/2 keeps the even correlator at 24/25.
(3) Each (R_k, L_k) marginal of E rho_R is diag(c_k^2, 0, 0, s_k^2); every (R_k, R_l), k != l, reduced
    state of E rho_R is the product of its marginals, while the ascended rho_R has non-product
    two-pair reduced states.
"""
from fractions import Fraction as F

import GA
import series
from tp_premise import premise

# --- exact multi-qubit simulator (states: dict {bitmask: amplitude}; qubit R_k = 2k, L_k = 2k+1) ---

def pair_state(c, s, k, state):
    """Tensor the thermofield pair c|00> + s|11> on (R_k, L_k) onto the state."""
    out = {}
    for m, a in state.items():
        out[m] = out.get(m, 0) + a * c
        m2 = m | (1 << (2 * k)) | (1 << (2 * k + 1))
        out[m2] = out.get(m2, 0) + a * s
    return {m: a for m, a in out.items() if a != 0}


def apply_cz(i, j, state):
    return {m: (-a if (m >> i) & 1 and (m >> j) & 1 else a) for m, a in state.items()}


def marginal(qubits, state, nq):
    """Reduced density matrix (unnormalised if the state is) over the listed qubits; bit t of the
    row index is the occupation of qubits[t]."""
    d = 1 << len(qubits)
    rho = [[F(0)] * d for _ in range(d)]
    rest = [q for q in range(nq) if q not in qubits]
    for m1, a1 in state.items():
        for m2, a2 in state.items():
            if all(((m1 >> r) & 1) == ((m2 >> r) & 1) for r in rest):
                i = sum(((m1 >> q) & 1) << t for t, q in enumerate(qubits))
                j = sum(((m2 >> q) & 1) << t for t, q in enumerate(qubits))
                rho[i][j] += a1 * a2
    return rho


mm = GA.mat_mul


def mtrace(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def purity(rho):
    d = len(rho)
    return sum((rho[i][j] * rho[j][i] for i in range(d) for j in range(d)), F(0))


def pinch(rho):
    """The descent E_N: complete dephasing in the joint number basis."""
    d = len(rho)
    return [[rho[i][j] if i == j else F(0) for j in range(d)] for i in range(d)]


def is_diag(rho):
    d = len(rho)
    return all(rho[i][j] == 0 for i in range(d) for j in range(d) if i != j)


def expect_xz(xs, zs, rho):
    """<prod_{i in xs} X_i prod_{j in zs} Z_j> against a density matrix (positions within its qubits)."""
    xmask = 0
    for i in xs:
        xmask ^= (1 << i)
    tot = F(0)
    for i in range(len(rho)):
        sign = 1
        for j in zs:
            if (i >> j) & 1:
                sign = -sign
        tot += rho[i ^ xmask][i] * sign
    return tot


def run_model(pairs, schedule, scramble=True):
    """The rate model: event t injects pair t (if any) and then evicts the oldest window qubits
    until |W| <= schedule[t], applying a controlled-Z between the two oldest window qubits before
    each eviction (number-diagonal scrambling). Returns stages [(state, radiation, window)]."""
    state = {0: F(1)}
    window, radiation, stages = [], [], []
    for t, cap in enumerate(schedule):
        if t < len(pairs):
            c, s = pairs[t]
            state = pair_state(c, s, t, state)
            radiation.append(2 * t)
            window.append(2 * t + 1)
        while len(window) > cap:
            if scramble and len(window) >= 2:
                state = apply_cz(window[0], window[1], state)
            radiation.append(window.pop(0))
        stages.append((dict(state), list(radiation), list(window)))
    return stages


def trace_cube(A):
    """tr A^3 with sparse rows."""
    rows = [[(j, x) for j, x in enumerate(r) if x != 0] for r in A]
    return sum((x * y * A[k][i] for i in range(len(A)) for j, x in rows[i] for k, y in rows[j]), F(0))

# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}


def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer (series.ln_bounds, memoised)."""
    if n not in _LNB:
        _LNB[n] = series.ln_bounds(n)
    return _LNB[n]


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

MODEL_PAIRS = [(F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(12, 13), F(5, 13))]
SCHEDULE = [2, 2, 2, 2, 1, 0]
NQ = 8


def H(c):
    return entropy([c * c, 1 - c * c])


def final_radiation():
    stages = run_model(MODEL_PAIRS, SCHEDULE)
    state, rad, win = stages[-1]
    return stages, marginal(sorted(rad), state, NQ)


def reduced(rho, keep):
    """Partial trace of a density matrix on qubits 0..n-1 onto the positions in keep."""
    d = 1 << len(keep)
    out = [[F(0)] * d for _ in range(d)]
    n = len(rho).bit_length() - 1
    rest = [q for q in range(n) if q not in keep]
    for i in range(len(rho)):
        for j in range(len(rho)):
            if rho[i][j] != 0 and all(((i >> r) & 1) == ((j >> r) & 1) for r in rest):
                a = sum(((i >> q) & 1) << t for t, q in enumerate(keep))
                b = sum(((j >> q) & 1) << t for t, q in enumerate(keep))
                out[a][b] += rho[i][j]
    return out


def kron2(A, B):
    """A on bit 0, B on bit 1."""
    return [[A[i & 1][j & 1] * B[i >> 1][j >> 1] for j in range(4)] for i in range(4)]


def check_ascended_and_descended_ledgers():
    premise("singularity.purity-correlation-transfer-recovery")
    stages, rhoR = final_radiation()
    ER = pinch(rhoR)
    prod = F(1)
    for c, s in MODEL_PAIRS:
        prod *= c ** 4 + s ** 4
    assert purity(rhoR) == 1 and purity(ER) == prod
    assert prod == F(817544276833, 6972900390625)
    S2 = LogVec.ln_rat(1 / prod)
    ln2 = LogVec.ln_int(2)
    assert logvec_lt(ln2 * F(308, 100), S2) and logvec_lt(S2, ln2 * F(310, 100))
    S_th = LogVec()
    for c, s in MODEL_PAIRS:
        S_th = S_th + H(c)
    assert entropy([ER[i][i] for i in range(len(ER))]) == S_th
    assert S_th == H(F(4, 5)) * 3 + H(F(12, 13))
    prev_S, prev_p, asc = None, None, []
    for state, rad, win in stages:
        rho_t = marginal(sorted(rad), state, NQ)
        E_t = pinch(rho_t)
        S_t = entropy([E_t[i][i] for i in range(len(E_t))])
        p_t = purity(E_t)
        assert p_t <= purity(rho_t)
        if prev_S is not None:
            assert logvec_le(prev_S, S_t) and p_t <= prev_p
        prev_S, prev_p = S_t, p_t
        rhoL = marginal(sorted(win), state, NQ)
        asc.append(entropy([rhoL[i][i] for i in range(len(rhoL))]))
    assert prev_S == S_th
    assert logvec_lt(asc[-1], asc[3]) and asc[-1] == LogVec() and logvec_lt(asc[0], asc[3])


def two_pair_histories():
    (c1, s1), (c2, s2) = MODEL_PAIRS[0], MODEL_PAIRS[1]
    plain = pair_state(c2, s2, 1, pair_state(c1, s1, 0, {0: F(1)}))
    return marginal([0, 1, 2, 3], plain, 4), marginal([0, 1, 2, 3], apply_cz(1, 3, plain), 4)


def check_deficit_located_and_message_not_descending():
    premise("singularity.deficit-theorem-cost-descent-exactly")
    premise("singularity.deficit-carried-quanta-correlations")
    premise("singularity.parity-protection")
    premise("singularity.p-reduced-metric-level-reading-many")
    stages, rhoR = final_radiation()
    ER = pinch(rhoR)
    S_th = LogVec()
    for c, s in MODEL_PAIRS:
        S_th = S_th + H(c)
    D = entropy([ER[i][i] for i in range(len(ER))]) - LogVec()     # S(rho_R) = 0: pure
    assert D == S_th and purity(rhoR) == 1
    for q in range(NQ):
        assert reduced(rhoR, [q]) == reduced(ER, [q])
        c, s = MODEL_PAIRS[q // 2]
        assert reduced(ER, [q]) == [[c * c, F(0)], [F(0), s * s]]
    plain, scr = two_pair_histories()
    assert (expect_xz([0, 1], [], scr), expect_xz([0, 1], [3], scr)) == (F(168, 625), F(24, 25))
    assert (expect_xz([0, 1], [], plain), expect_xz([0, 1], [3], plain)) == (F(24, 25), F(168, 625))
    for rho in (plain, scr):
        Er = pinch(rho)
        assert expect_xz([0, 1], [], Er) == 0 and expect_xz([0, 1], [3], Er) == 0
    # total-parity average: Gamma = (-1)^N is diagonal; (rho + Gamma rho Gamma)/2 keeps even correlators
    par = [(-1) ** bin(i).count("1") for i in range(16)]
    avg = [[(scr[i][j] + par[i] * scr[i][j] * par[j]) / 2 for j in range(16)] for i in range(16)]
    assert avg == scr and expect_xz([0, 1], [3], avg) == F(24, 25)


def check_records_survive_inter_pair_destroyed():
    stages, rhoR = final_radiation()
    ER = pinch(rhoR)
    for k, (c, s) in enumerate(MODEL_PAIRS):
        pk = reduced(ER, [2 * k, 2 * k + 1])
        assert pk == [[c * c, F(0), F(0), F(0)], [F(0)] * 4, [F(0)] * 4, [F(0), F(0), F(0), s * s]]
    n_pairs = len(MODEL_PAIRS)
    for k in range(n_pairs):
        for l in range(k + 1, n_pairs):
            joint = reduced(ER, [2 * k, 2 * l])
            assert joint == kron2(reduced(ER, [2 * k]), reduced(ER, [2 * l]))
    # the ascended radiation does carry inter-pair correlation (scrambled neighbours)
    nonproduct = 0
    for k in range(n_pairs - 1):
        a, b = [2 * k, 2 * k + 1], [2 * k + 2, 2 * k + 3]
        four = reduced(rhoR, a + b)
        A, B = reduced(rhoR, a), reduced(rhoR, b)
        prodAB = [[A[i & 3][j & 3] * B[i >> 2][j >> 2] for j in range(16)] for i in range(16)]
        nonproduct += four != prodAB
    assert nonproduct == 3

singularity.what-event-returns-radiation:
"""singularity.what-event-returns-radiation: exact checks of what an emission event returns.

Rate-model runs on exact amplitudes (qubits R_k = 2k, L_k = 2k+1; controlled-Z before each eviction):
the model table's run (five events with a block), a five-pair run whose schedule 3,3,3,1,1,0 evicts
three qubits in one event, and the maximally entangled idealisation (amplitudes 1, 1) with one eviction
per event. At each event A is the new radiation block (R_k and the evicted L_j), R_< the earlier
radiation. All entropies are exact formal logarithms of exact rational spectra: rho_A is checked
diagonal; S(R_<) and S(A u R_<) are read from the (diagonal) window before and after by global purity,
which is re-checked through equal purities where the radiation has at most six qubits.
(1) S(rho_A) = h_k + sum_{evicted} h_j and I(A : R_<) = 2 sum_{evicted} h_j at every event.
(2) Each evicted L_j has I(L_j : R_<) = 2 h_j (checked at every eviction of the model run and of the
    five-pair run on the schedule 3,3,3,3,3,2,1,0, where the complement's entropy is diagonal-readable:
    the new pair, if any, is verified to be an untouched pure factor), while I(L_j : R_j) < 2 h_j once
    a gate has acted: the (R_j, L_j) marginal keeps the populations c^2, s^2, its coherence is damped
    below c s and its purity is below 1, so S(R_j L_j) > 0.
(3) In the idealisation, I(A : R_<) = 2 ln 2 = S(rho_A) at every event with one eviction.
"""
from fractions import Fraction as F

import GA
import series
from tp_premise import premise

# --- exact multi-qubit simulator (states: dict {bitmask: amplitude}; qubit R_k = 2k, L_k = 2k+1) ---

def pair_state(c, s, k, state):
    """Tensor the thermofield pair c|00> + s|11> on (R_k, L_k) onto the state."""
    out = {}
    for m, a in state.items():
        out[m] = out.get(m, 0) + a * c
        m2 = m | (1 << (2 * k)) | (1 << (2 * k + 1))
        out[m2] = out.get(m2, 0) + a * s
    return {m: a for m, a in out.items() if a != 0}


def apply_cz(i, j, state):
    return {m: (-a if (m >> i) & 1 and (m >> j) & 1 else a) for m, a in state.items()}


def marginal(qubits, state, nq):
    """Reduced density matrix (unnormalised if the state is) over the listed qubits; bit t of the
    row index is the occupation of qubits[t]."""
    d = 1 << len(qubits)
    rho = [[F(0)] * d for _ in range(d)]
    rest = [q for q in range(nq) if q not in qubits]
    for m1, a1 in state.items():
        for m2, a2 in state.items():
            if all(((m1 >> r) & 1) == ((m2 >> r) & 1) for r in rest):
                i = sum(((m1 >> q) & 1) << t for t, q in enumerate(qubits))
                j = sum(((m2 >> q) & 1) << t for t, q in enumerate(qubits))
                rho[i][j] += a1 * a2
    return rho


mm = GA.mat_mul


def mtrace(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def purity(rho):
    d = len(rho)
    return sum((rho[i][j] * rho[j][i] for i in range(d) for j in range(d)), F(0))


def pinch(rho):
    """The descent E_N: complete dephasing in the joint number basis."""
    d = len(rho)
    return [[rho[i][j] if i == j else F(0) for j in range(d)] for i in range(d)]


def is_diag(rho):
    d = len(rho)
    return all(rho[i][j] == 0 for i in range(d) for j in range(d) if i != j)


def expect_xz(xs, zs, rho):
    """<prod_{i in xs} X_i prod_{j in zs} Z_j> against a density matrix (positions within its qubits)."""
    xmask = 0
    for i in xs:
        xmask ^= (1 << i)
    tot = F(0)
    for i in range(len(rho)):
        sign = 1
        for j in zs:
            if (i >> j) & 1:
                sign = -sign
        tot += rho[i ^ xmask][i] * sign
    return tot


def run_model(pairs, schedule, scramble=True):
    """The rate model: event t injects pair t (if any) and then evicts the oldest window qubits
    until |W| <= schedule[t], applying a controlled-Z between the two oldest window qubits before
    each eviction (number-diagonal scrambling). Returns stages [(state, radiation, window)]."""
    state = {0: F(1)}
    window, radiation, stages = [], [], []
    for t, cap in enumerate(schedule):
        if t < len(pairs):
            c, s = pairs[t]
            state = pair_state(c, s, t, state)
            radiation.append(2 * t)
            window.append(2 * t + 1)
        while len(window) > cap:
            if scramble and len(window) >= 2:
                state = apply_cz(window[0], window[1], state)
            radiation.append(window.pop(0))
        stages.append((dict(state), list(radiation), list(window)))
    return stages


def trace_cube(A):
    """tr A^3 with sparse rows."""
    rows = [[(j, x) for j, x in enumerate(r) if x != 0] for r in A]
    return sum((x * y * A[k][i] for i in range(len(A)) for j, x in rows[i] for k, y in rows[j]), F(0))

# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}


def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer (series.ln_bounds, memoised)."""
    if n not in _LNB:
        _LNB[n] = series.ln_bounds(n)
    return _LNB[n]


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

MODEL_PAIRS = [(F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(4, 5), F(3, 5)), (F(12, 13), F(5, 13))]
PAIRS_B = [(F(24, 25), F(7, 25)), (F(3, 5), F(4, 5)), (F(12, 13), F(5, 13)), (F(20, 29), F(21, 29)),
           (F(8, 17), F(15, 17))]
IDEAL = [(F(1), F(1))] * 5
RUNS = [(MODEL_PAIRS, [2, 2, 2, 2, 1, 0]), (PAIRS_B, [3, 3, 3, 1, 1, 0]), (IDEAL, [2, 2, 2, 2, 2, 1, 0])]


def h(pair):
    c, s = pair
    n = c * c + s * s
    return entropy([c * c / n, s * s / n])


def diag_entropy(rho):
    assert is_diag(rho)
    return entropy([rho[i][i] for i in range(len(rho))])


def events(pairs, schedule):
    nq = 2 * len(pairs)
    stages = run_model(pairs, schedule)
    out = []
    for t in range(1, len(stages)):
        (sp, radp, winp), (st, rad, win) = stages[t - 1], stages[t]
        A = sorted(set(rad) - set(radp))
        if not A:
            continue
        nrm = sum(a * a for a in st.values())
        nrmp = sum(a * a for a in sp.values())
        norm = lambda r, n: [[x / n for x in row] for row in r]
        rA = norm(marginal(A, st, nq), nrm)
        rWp = norm(marginal(sorted(winp), sp, nq), nrmp)
        rW = norm(marginal(sorted(win), st, nq), nrm)
        if len(radp) <= 6:
            assert purity(norm(marginal(sorted(radp), sp, nq), nrmp)) == purity(rWp)
        if len(rad) <= 6:
            assert purity(norm(marginal(sorted(rad), st, nq), nrm)) == purity(rW)
        out.append((A, diag_entropy(rA), diag_entropy(rWp), diag_entropy(rW), st, nq, nrm))
    return out


def check_block_entropy_and_returned_information():
    premise("singularity.eviction-window-thermal-product-radiation-entropy")
    for (pairs, schedule), want in zip(RUNS, (5, 5, 6)):
        evs = events(pairs, schedule)
        assert len(evs) == want
        two_at_once = 0
        for A, S_A, S_Rl, S_all, st, nq, nrm in evs:
            new = [q // 2 for q in A if q % 2 == 0]
            ev = [q // 2 for q in A if q % 2 == 1]
            two_at_once += len(ev) >= 2
            want_SA, want_I = LogVec(), LogVec()
            for k in new + ev:
                want_SA = want_SA + h(pairs[k])
            for j in ev:
                want_I = want_I + h(pairs[j]) * 2
            assert S_A == want_SA
            assert S_A + S_Rl - S_all == want_I
        assert two_at_once == (1 if pairs is PAIRS_B else 0)


def factorises(rho, X, Y, C):
    """rho over the qubit list C equals rho_X (x) rho_Y, X u Y = C (lists of qubits)."""
    pX, pY = [C.index(q) for q in X], [C.index(q) for q in Y]
    rX, rY = reduce_to(rho, pX), reduce_to(rho, pY)
    sub = lambda i, ps: sum(((i >> p) & 1) << t for t, p in enumerate(ps))
    return all(rho[i][j] == rX[sub(i, pX)][sub(j, pX)] * rY[sub(i, pY)][sub(j, pY)]
               for i in range(len(rho)) for j in range(len(rho))), rX, rY


def reduce_to(rho, keep):
    n = len(rho).bit_length() - 1
    rest = [p for p in range(n) if p not in keep]
    d = 1 << len(keep)
    out = [[F(0)] * d for _ in range(d)]
    for i in range(len(rho)):
        for j in range(len(rho)):
            if rho[i][j] != 0 and all(((i >> r) & 1) == ((j >> r) & 1) for r in rest):
                out[sum(((i >> p) & 1) << t for t, p in enumerate(keep))][
                    sum(((j >> p) & 1) << t for t, p in enumerate(keep))] += rho[i][j]
    return out


def check_evicted_qubit_correlated_with_radiation_not_partner():
    premise("singularity.purity-correlation-transfer-recovery")
    for (pairs, schedule), want in zip((RUNS[0], (PAIRS_B, [3, 3, 3, 3, 3, 2, 1, 0])), (4, 5)):
        nq = 2 * len(pairs)
        stages = run_model(pairs, schedule)
        n_checked = 0
        for t in range(1, len(stages)):
            (sp, radp, winp), (st, rad, win) = stages[t - 1], stages[t]
            A = sorted(set(rad) - set(radp))
            newR = [q for q in A if q % 2 == 0]
            for q in [q for q in A if q % 2 == 1]:
                j = q // 2
                c, s = pairs[j]
                # the partner pair (R_j, L_j): populations kept, coherence damped, purity < 1
                pair = marginal([2 * j, q], st, nq)
                assert pair[0][0] == c * c and pair[3][3] == s * s
                assert pair[0][3] ** 2 < (c * s) ** 2 and purity(pair) < 1
                # I(L_j : R_<) through the complement W u A minus L_j (global purity)
                comp = sorted(set(win) | set(A) - {q})
                rC = marginal(comp, st, nq)
                if newR:
                    k = newR[0] // 2
                    if len(comp) > 6:
                        continue
                    fac, rX, rY = factorises(rC, [x for x in comp if x // 2 != k], [2 * k, 2 * k + 1], comp)
                    if not fac or purity(rY) != 1:
                        continue
                    S_comp = diag_entropy(rX)
                else:
                    S_comp = diag_entropy(rC)
                S_Rl = diag_entropy(marginal(sorted(winp), sp, nq))
                assert diag_entropy(marginal([q], st, nq)) + S_Rl - S_comp == h(pairs[j]) * 2
                n_checked += 1
        assert n_checked == want


def check_idealisation_returns_two_ln_two():
    ln2 = LogVec.ln_int(2)
    pairs, schedule = RUNS[2]
    n_one = 0
    for A, S_A, S_Rl, S_all, st, nq, nrm in events(pairs, schedule):
        ev = [q for q in A if q % 2 == 1]
        if len(ev) == 1 and len(A) == 2:
            n_one += 1
            assert S_A == ln2 * 2 and S_A + S_Rl - S_all == ln2 * 2
    assert n_one == 3
